        public static bool DocApprovalRequired_Get(int docCodeKey, ref bool ntApprovalReq) 
        {
            try
            {
                bool docApprovalReq = false;
                List<SqlParameter> parmList = new List<SqlParameter>();
                parmList.Add(new SqlParameter("@DocCodeKey", docCodeKey));                

                DataTable dt = GFunc.ExecuteProc("SysOpApprovalRequired_Get", parmList);

                if (dt != null && dt.Rows.Count > 0)
                {
                    docApprovalReq = GFunc.NEBool(dt.Rows[0]["DocApprovalRequired"], false);
                    ntApprovalReq = GFunc.NEBool(dt.Rows[0]["NontradeApprovalRequired"],false);
                }

                dt = null;
                return docApprovalReq; 
            }           
            catch
            {
                return false;                
            }
        }
