        public static void StatusBarUpdate(System.Windows.Forms.Form frm, int status)
        {
            if (frm != null)
            {
                UltraStatusBar statusbar = new UltraStatusBar();
                statusbar = (UltraStatusBar)frm.Controls.Find("ustsbarMain", true)[0];

                if (status == 1)
                {
                    statusbar.Panels["ChildStatus"].Text = "Checking profit margin & quotation limit ...............";
                    statusbar.Panels["ChildStatus"].Appearance.FontData.Bold = DefaultableBoolean.True;
                    statusbar.Panels["ChildStatus"].Appearance.FontData.SizeInPoints = 11;
                    statusbar.Panels["ChildStatus"].Appearance.ForeColor = System.Drawing.Color.DarkRed;
                    statusbar.Refresh();
                }
                else if (status == 0)
                {
                    statusbar.Panels["ChildStatus"].Text = "Ready";
                    statusbar.Panels["ChildStatus"].Appearance.FontData.Bold = DefaultableBoolean.False;
                    statusbar.Panels["ChildStatus"].Appearance.FontData.SizeInPoints = statusbar.Panels["Status"].Appearance.FontData.SizeInPoints;
                    statusbar.Panels["ChildStatus"].Appearance.ForeColor = statusbar.Panels["Status"].Appearance.ForeColor;
                    statusbar.Refresh();
                }
            }
        }
        public static decimal GetCostOfSaleTotal(DataTable dt)
        {
            decimal sum = 0;
            foreach (DataRow dr in dt.Rows)
            {
                sum += GFunc.NEDec(dr["CostOfSale"], 0);
            }
            return sum;
        }
