        public static DataTable CostOfSaleList(DataTable dt, Document objDoc)
        {
            dt.TableName = "dtItmData";
            string DocItmXML = GFunc.ConvertDataTableToXML(dt);

            List<SqlParameter> parmList = new List<SqlParameter>();

            parmList.Add(new SqlParameter("@QuotationDetailData", DocItmXML));
            parmList.Add(new SqlParameter("@TranDate", (DateTime)objDoc.DocDate));
            parmList.Add(new SqlParameter("@CurrRate", (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc)));
            return GFunc.ExecuteProc("CheckingProfitMarginForIndividualItem", parmList);
        }
