        //Document Posting Process Post
        private static bool Doc_Posting(Document objDoc, Hashtable dtDetails, int ButtonAction, DataTable dtSvrData, bool ApprovalReq, bool Authorised, out string DocAutoID, out int NewDocState, System.Windows.Forms.Form frm = null)
        {

            #region Declaration
            bool postingLockAdded = false;
            int? inProgressKey = -1000;
            int? dataKey = 0;
            int docConKey = 0;
            int docGrpKey = 0;
            GEnum.SysLockOption option = GEnum.SysLockOption.ByCodeKeyAndDataKeyAndInprogressKeyAndGUID;
            NewDocState = 0;
            DocAutoID = string.Empty;
            bool cancelProcess = false;

            string UpType = string.Empty;
            bool UpItmHis = false;
            bool UpStock = false;
            bool UpCust = false;
            bool UpVend = false;
            bool UpAcc = false;

            bool userContinueOutofStock = false;
            bool userContinueLocOutofStock = false;
            bool userContinueCLExceeded = false;
            bool userContinueTermExceeded = false;

            DataTable dtDocDetItm = null;   //Caller Document Detail Items
            DataTable dtDocDetExp = null;   //Caller Document Detail Expenses

            //for Saving
            DataTable dsItems = null;       //working table for MSTItm, MSTItmLoc and MSTItmHis update
            DataTable dsItemsBatch = null;  //working table for MSTItmBatch, MSTItmBatchLog update
            DataTable dtCV = null;          //working table for MSTCon, MSTConHis update
            DataTable dtPost = null;        //working table for Posting GLLog update

            int counterLastID = -999;       //For Updating LastIDCounter (we use a -ve value to indicate that there no need to update the SYSIDCounter table
            int counterPeriod = 0;
            int counterDocGrpKey = 0;
            int counterConKey = 0;
            int counterEMKey = 0;
            string counterGrpStr = string.Empty;

            int OldDocState = objDoc.DocState.Value;
            SYSAttachments objSYSAttachments = null;
            #endregion

            try
            {
                #region get Detail DataTable from hashtable
                switch (objDoc.DocCodeKey)
                {
                    case (int)GEnum.SystemCode.Quotation:
                    case (int)GEnum.SystemCode.Purchase_Plan:
                    case (int)GEnum.SystemCode.Purchase_Request:
                    case (int)GEnum.SystemCode.Sales_Order:
                    case (int)GEnum.SystemCode.Reserve_Order:
                    case (int)GEnum.SystemCode.Purchase_Order:
                    case (int)GEnum.SystemCode.Order_Consignment:
                    case (int)GEnum.SystemCode.Sales_Order_Adjustment:
                    case (int)GEnum.SystemCode.Purchase_Order_Adjustment:
                    case (int)GEnum.SystemCode.Consignment_Order_Adjustment:
                    case (int)GEnum.SystemCode.Delivery_Order:
                    case (int)GEnum.SystemCode.Purchase_Shipment:
                    case (int)GEnum.SystemCode.Purchase_Delivery:
                    case (int)GEnum.SystemCode.Received_Consignment:
                    case (int)GEnum.SystemCode.Packing_List:
                    case (int)GEnum.SystemCode.Consignment_Settlement:
                    case (int)GEnum.SystemCode.Sales_Invoice:
                    case (int)GEnum.SystemCode.Sales_Debit_Note:
                    case (int)GEnum.SystemCode.Sales_Credit_Note:
                    case (int)GEnum.SystemCode.Cash_Sale:
                    case (int)GEnum.SystemCode.Cash_Debit_Note:
                    case (int)GEnum.SystemCode.Cash_Credit_Note:
                    case (int)GEnum.SystemCode.Purchase_Invoice:
                    case (int)GEnum.SystemCode.Purchase_Debit_Note:
                    case (int)GEnum.SystemCode.Purchase_Credit_Note:
                    case (int)GEnum.SystemCode.Contra:
                    case (int)GEnum.SystemCode.Cash_Contra:
                    case (int)GEnum.SystemCode.Inventory_Adjustment:
                    case (int)GEnum.SystemCode.Inventory_Production:
                    case (int)GEnum.SystemCode.Inventory_Transfer:
                    case (int)GEnum.SystemCode.Journal:
                    case (int)GEnum.SystemCode.Deposit:
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Itm, dtDetails, ref dtDocDetItm);
                        break;
                    case (int)GEnum.SystemCode.Issue_Consignment:
                    case (int)GEnum.SystemCode.Return_Consignment:
                    case (int)GEnum.SystemCode.Payment_Received:
                    case (int)GEnum.SystemCode.Cash_Payment_Received:
                    case (int)GEnum.SystemCode.Payment_Issue:
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Itm, dtDetails, ref dtDocDetItm);
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Exp, dtDetails, ref dtDocDetExp);
                        break;
                }
                #endregion

                #region Get process to run in posting
                if (Doc_SetSaveProcess(objDoc, ButtonAction, ApprovalReq, Authorised, ref NewDocState, ref UpType, ref UpItmHis, ref UpStock, ref UpCust, ref UpVend, ref UpAcc) == false)
                    return false;
                #endregion

                #region Add Posting Lock
                if (ButtonAction != (int)GEnum.DocAction.Delete && objDoc.DocState == (int)GEnum.DocState.New)
                {
                    if (SysLockUtility.AddPostingLock(false, objDoc.GUID, (GEnum.SystemCode)objDoc.DocCodeKey))
                    {
                        postingLockAdded = true;
                    }
                    else
                    {
                        bool showmsg = false;
                        SYSLock obj = SYSLock.Get((GEnum.SystemCode)objDoc.DocCodeKey, 0, -1000);
                        if (!GFunc.IsNEZ(obj._userKey))
                        {

                            SECUser objuser = SECUser.Get(obj._userKey);
                            if (!GFunc.IsNEZ(objuser.UserKey))
                                MsgBox.Show("Another session is in progress by " + objuser.UserID + " , Please try again a few seconds later");
                            else
                                showmsg = true;
                        }
                        else
                            showmsg = true;

                        if (showmsg)
                            MsgBox.Show("Another session is in progress, Please try again a few seconds later");
                        return false;
                    }
                }
                #endregion

                #region  Prepare Itm History for the 1st time, getting user action when Out of Stock

                dsItems = Doc_Item_Prepare(objDoc, NewDocState, dtDocDetItm, UpType, UpStock, UpItmHis, out cancelProcess, ref userContinueOutofStock, ref userContinueLocOutofStock, true);
                if (cancelProcess)
                    return false;

                #endregion

                #region  Prepare Customer History for the 1st time, getting user action when exceeded Limits
                dtCV = Doc_CV_Prepare(objDoc, dtDocDetItm, dtSvrData, UpType, out cancelProcess, ref userContinueCLExceeded, ref userContinueTermExceeded, true,ButtonAction).Copy();
                if (cancelProcess)
                    return false;

                    
                #endregion

                #region  Prepare Itm History for the 2nd time

                dsItems = Doc_Item_Prepare(objDoc, NewDocState, dtDocDetItm, UpType, UpStock, UpItmHis, out cancelProcess, ref userContinueOutofStock, ref userContinueLocOutofStock, false );
                if (cancelProcess)
                    return false;

                #endregion

                #region  Prepare Customer History for 2nd time
                dtCV = Doc_CV_Prepare(objDoc, dtDocDetItm, dtSvrData, UpType, out cancelProcess, ref userContinueCLExceeded, ref userContinueTermExceeded, false,ButtonAction).Copy();
                if (cancelProcess)
                    return false;


