                                case (int)GEnum.SystemCode.Reserve_Order:
                                case (int)GEnum.SystemCode.Delivery_Order:
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                    DataRow[] drs = dtDocDetItm.Select("ItmJobKey<>0");
                                    if (drs.Length > 0)
                                    {
                                        JobKey = GFunc.NEInt(drs[0]["ItmJobKey"], 0);
                                    }
                                    break;
                            }
                            #endregion
                            //Added on 22 Aug 2021 -End
                            //Modified on 22 Aug 2021
                           // if (SysIDCounterUtility.Get(out DocAutoID, out counterGrpStr, out counterLastID, out counterPeriod, out counterDocGrpKey, out counterConKey, out counterEMKey, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.DocTypeNm, docGrpKey, docConKey, objDoc.DocEmKey, objDoc.DocDate.Value))
                            if (SysIDCounterUtility.Get(out DocAutoID, out counterGrpStr, out counterLastID, out counterPeriod, out counterDocGrpKey, out counterConKey, out counterEMKey, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.DocTypeNm, docGrpKey, docConKey, JobKey, objDoc.DocDate.Value))
                                objDoc.DocID = DocAutoID;
                            else
                                return false;

                            #endregion
                        }
                        else
                        {
                            #region Check Duplicate DocID
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Purchase_Shipment:
                                case (int)GEnum.SystemCode.Purchase_Delivery:
