                                    docConKey = GFunc.NEInt((int)GFunc.GetIntPropertyValue("DocConKey", objDoc), 0);
                                    if (SysIDCounterUtility.DuplicateFound(objDoc.DocID, (GEnum.SystemCode)objDoc.DocCodeKey, docConKey, 0, 0))
