                                    {
                                        MsgBox.Show("DocID" + MsgID.Validation.DuplicateRecord);
                                        return false;
                                    }
                                    break;
                            }
                            #endregion
                        }
                    }
                }
                #endregion

                //Prepare Posting      
                dtPost = Doc_Posting_Prepare(objDoc, ButtonAction, dtDetails, DocAutoID);

                //bool validationforapproval = true;
                //bool DirtyState = false;

                //if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation && objDoc.DocEmKey!=SysOptionUtility.GetInt("DraftingSaleRep"))
                //{
                //    if (GFunc.NEDec(GFunc.GetPropertyValue("DocSubTotal", objDoc), 0) > 0)
