                //                            Int16 teamleader = Int16.Parse(GFunc.ExecuteScalar(cn, "if exists(select 1 from MST_SalesApprover where ApproverKey ='" + objDoc.DocEmKey.ToString() + "' ) select 1 else select 0").ToString());
                //                            if (teamleader == 1)
                //                                CheckingForSaleLeaderLevelForNoti(dtDocDetItm, objDoc, dtDetails, dsItems, dtCV, dtPost, ButtonAction, UpType, UpItmHis, UpStock, UpCust, UpVend, UpAcc, objDoc.DocID, counterGrpStr, counterLastID, counterPeriod, counterDocGrpKey, counterConKey, counterEMKey, frm);
                //                            else
                //                            {
                //                                int approverSaleId = GFunc.NEInt(GFunc.ExecuteScalar(cn, "select ApproverKey from MST_SalesApprover where SaleRepKey=" + objDoc.DocEmKey.ToString()).ToString(), 0);
                //                                if (approverSaleId > 0)
                //                                    CheckingForSaleCoordinatorForNoti(dtDocDetItm, objDoc, dtDetails, dsItems, dtCV, dtPost, ButtonAction, UpType, UpItmHis, UpStock, UpCust, UpVend, UpAcc, objDoc.DocID, counterGrpStr, counterLastID, counterPeriod, counterDocGrpKey, counterConKey, counterEMKey, frm);
                //                                else
                //                                {
                //                                    MsgBox.Show("Please set up for approvers in your account!");
                //                                    return true;
                //                                }
                //                            }
                //                            cn.Close();
                //                        }
                //                    }
                //                }
                //                else if (objDoc.Custom5 == "PROJECT" || objDoc.Custom5 == "GSW")
                //                {
                //                    if (ButtonAction == 4 || ButtonAction == 1)
                //                    {
                //                        if (objDoc.DocEmKey == SysOptionUtility.GetInt("DefaultFinalAprover1"))
                //                            validationforapproval = CheckingForManagementLevelForApproval(dtDocDetItm, objDoc);
                //                        else
                //                        {
                //                            SqlConnection cn = new SqlConnection(AppInfor.currentDBConnectionStr);
                //                            cn.Open();
                //                            Int16 teamleader = Int16.Parse(GFunc.ExecuteScalar(cn, "if exists(select 1 from MST_SalesApprover where ApproverKey ='" + objDoc.DocEmKey.ToString() + "' ) select 1 else select 0").ToString());

                //                            if (teamleader == 1)
                //                                validationforapproval = CheckingForSaleLeaderLevelForApproval(dtDocDetItm, objDoc, dtDetails, dsItems, dtCV, dtPost, ButtonAction, UpType, UpItmHis, UpStock, UpCust, UpVend, UpAcc, objDoc.DocID, counterGrpStr, counterLastID, counterPeriod, counterDocGrpKey, counterConKey, counterEMKey, frm);
                //                            else
                //                            {
                //                                bool approverSaleId = GFunc.NEBool(GFunc.ExecuteScalar(cn, "if exists(select ApproverKey from MST_SalesApprover where SaleRepKey=" + objDoc.DocEmKey.ToString() + ") select 1 else select 0").ToString(), false);
                //                                if (approverSaleId)
                //                                    validationforapproval = CheckingForSaleCoordinatorForApproval(dtDocDetItm, objDoc, dtDetails, dsItems, dtCV, dtPost, ButtonAction, UpType, UpItmHis, UpStock, UpCust, UpVend, UpAcc, objDoc.DocID, counterGrpStr, counterLastID, counterPeriod, counterDocGrpKey, counterConKey, counterEMKey, frm);
                //                                else
                //                                {
                //                                    MsgBox.Show("Please set up for approvers in your account!");
                //                                    return true;
                //                                }
                //                            }
                //                            cn.Close();
                //                        }
                //                    }
                //                }
                //        }

                //    }
                //}


                //#endregion
                bool notiQO = SysOptionUtility.GetBool("DocNotiForQO");
                using (TransactionScope scope = new TransactionScope(TransactionScopeOption.Required, GetTransOption()))
                {
                    using (SqlConnection cn = new SqlConnection(AppInfor.currentDBConnectionStr))
                    {
                        cn.Open();
                        if (BatchQty_Check(cn, objDoc, dtDocDetItm, false, ButtonAction) == false)
                        {
                            MsgBox.Show(cn, MsgID.Common.ValidationFail + "%Batch Qty");
                            return false;
                        }

                        #region  Prepare Itm Batch History
                        switch (objDoc.DocCodeKey)
                        {
                            case (int)GEnum.SystemCode.Delivery_Order:
                            case (int)GEnum.SystemCode.Sales_Invoice:
                            case (int)GEnum.SystemCode.Sales_Credit_Note:
                            case (int)GEnum.SystemCode.Sales_Debit_Note:
                            case (int)GEnum.SystemCode.Cash_Sale:
                            case (int)GEnum.SystemCode.Cash_Credit_Note:
                            case (int)GEnum.SystemCode.Cash_Debit_Note:
                            case (int)GEnum.SystemCode.Purchase_Shipment:
                            case (int)GEnum.SystemCode.Purchase_Delivery:
                            case (int)GEnum.SystemCode.Purchase_Invoice:
                            case (int)GEnum.SystemCode.Purchase_Credit_Note:
                            case (int)GEnum.SystemCode.Purchase_Debit_Note:
                            case (int)GEnum.SystemCode.Inventory_Adjustment:
                            case (int)GEnum.SystemCode.Inventory_Production:
                            case (int)GEnum.SystemCode.Inventory_Transfer:
                            case (int)GEnum.SystemCode.Issue_Consignment:
                            case (int)GEnum.SystemCode.Return_Consignment:
                                dsItemsBatch = Doc_ItemBatch_Prepare(cn, objDoc, NewDocState, dtDocDetItm, UpType, UpStock, UpItmHis, out cancelProcess);
                                if (cancelProcess)
                                    return false;
                                break;

                            default:
                                dsItemsBatch = new DataTable();    //need to have an empty dataset as it is required in the Doc_Update() later
                                break;
                        }
                        #endregion
                        if (
                            notiQO == true
                            && objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation
                            && (int)ButtonAction == 4
                            //&& (objDoc.Custom5 == "BD" || objDoc.Custom5 == "PROJECT" || objDoc.Custom5 == "GSW") /* commented by YST on 2022/06/30 to show Progress Loading to all */
                           )
                           StatusBarUpdate(frm, 1);
                        //Perform actual posting to server data
                        //if ((objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation && validationforapproval) || objDoc.DocCodeKey != (int)GEnum.SystemCode.Quotation)
                        if (!Doc_Update(cn, objDoc, dtDetails, dsItems, dsItemsBatch, dtCV, dtPost, ButtonAction, NewDocState, UpType, UpItmHis, UpStock, UpCust, UpVend, UpAcc, objDoc.DocID, counterGrpStr, counterLastID, counterPeriod, counterDocGrpKey, counterConKey, counterEMKey))
                            throw new Exception("Posting failed.");

                        if (
                            notiQO == true
                            && objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation
                            && (int)ButtonAction == 4
                            //&& (objDoc.Custom5 == "BD" || objDoc.Custom5 == "PROJECT" || objDoc.Custom5 == "GSW") /* commented by YST on 2022/06/30 to show Progress Loading to all */
                           )
                           StatusBarUpdate(frm, 0);

                        //All Documents have attachements                       
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Attachment, dtDetails, ref objSYSAttachments);
                            
                        //if(!((objDoc.DocCodeKey == (int)GEnum.SystemCode.Delivery_Order
                        //    || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order
                        //    || objDoc.DocCodeKey == (int)GEnum.SystemCode.Cash_Sale
                        //    || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Invoice
                        //    || objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation)   // added by KKAung on 16 Feb 2023
                        //    && SysOptionUtility.HasDMASLink))//Added by May on 30 Nov 2021.. if Link to DMAS, DO will save once files are attached
                        //    AttachmentSave(cn, objSYSAttachments,(GEnum.SystemCode) objDoc.DocCodeKey,objDoc.DocKey);                            

                        //Update objDoc(DocID,DocState) with newDocID and newDocState
                        //if ((objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation && validationforapproval) || objDoc.DocCodeKey != (int)GEnum.SystemCode.Quotation)//ttm
                        if (OldDocState == (int)GEnum.DocState.New)
                        {
                            if (objDoc.DocID == string.Empty && DocAutoID != string.Empty)
                                objDoc.DocID = DocAutoID;
                            objDoc.DocState = NewDocState;
                            SysLockUtility.AddLock(cn, true, objDoc.GUID, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.DocKey);
                        }

                        if ((SysOptionUtility.DatabaseBranchCode == "BHM" || SysOptionUtility.DatabaseBranchCode == "GLH") &&
                            (int)ButtonAction == (int)GEnum.DocAction.Post &&
                            (objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation ||
                            objDoc.DocCodeKey == (int)GEnum.SystemCode.Reserve_Order ||
                            objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order))
                        {
                            /* added by YST on 2022/06/30 to bind DocSate that updated in SQL_Save funtion */
                            List<SqlParameter> lstParam = new List<SqlParameter>();
                            lstParam.Add(new SqlParameter("@DocKey", objDoc.DocKey));
                            lstParam.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                            string UpdatedDocState = GFunc.ExecuteScalar(cn, "DocState_Get", lstParam);
                            objDoc.DocState = Convert.ToInt16(UpdatedDocState);
                        }

                        /* commented by YST on 2022/06/30 */
                        //if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation && (int)ButtonAction == 4)
                        //    objDoc.DocState = Int32.Parse(GFunc.ExecuteScalar(cn, "select docstate from ar_qo where dockey=" + objDoc.DocKey.ToString()).ToString());

                        if (Transaction.Current.TransactionInformation.Status != TransactionStatus.Active)
                            throw new Exception("Transaction has aborted.");
                        scope.Complete();
                    }
                }
                //added by thettm on 04 nov 2018(start) to sync estore Qty
                if (UpStock == true && SysOptionUtility.DatabaseBranchCode == "BHM" && objDoc.DocCodeKey != (int)GEnum.SystemCode.Cash_Sale)
                {
                    SqlConnection cn = new SqlConnection(AppInfor.currentDBConnectionStr);
                    DataTable dsItmHis = dsItems;
                    dsItmHis.TableName = "dtItmHis";
                    string XMLformat = "";
                    XMLformat = GFunc.ConvertDataTableToXML(dsItmHis);
                    List<SqlParameter> paraList = new List<SqlParameter>();
                    paraList.Add(new SqlParameter("@xmlDocItmHis", XMLformat));
                    cn.Open();
                    GFunc.ExecuteNonQueryProc(cn, "[Update_To_Estore]", paraList);
                    cn.Close();
                }

                //added by infosolve 18-Sep-2020
                //SendAttachmentToDMAS(objSYSAttachments, objDoc);

            }
            catch (TAException taex)
            {
                throw Error(taex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
            finally
            {
                dtDocDetItm = null;
                dsItems = null;
                dtCV = null;
                dtDocDetExp = null;
                dtPost = null;
                if (postingLockAdded)
                    SysLockUtility.RemoveLock(true, option, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.GUID, dataKey, inProgressKey);
            }
            return true;
        }//Completed
        private static bool Doc_Posting(SqlConnection cn, Document objDoc, Hashtable dtDetails, int ButtonAction, DataTable dtSvrData, bool ApprovalReq, bool Authorised, out string DocAutoID, out int NewDocState, int MultiProcessDocCode)
        {

            #region Declaration
            bool postingLockAdded = false;
            int? inProgressKey = -1000;
            int? dataKey = 0;
            int docConKey = 0;
            int docGrpKey = 0;
            GEnum.SysLockOption option = GEnum.SysLockOption.ByCodeKeyAndDataKeyAndInprogressKeyAndGUID;
            NewDocState = 0;
            DocAutoID = string.Empty;
            bool cancelProcess = false;

            string UpType = string.Empty;
            bool UpItmHis = false;
            bool UpStock = false;
            bool UpCust = false;
            bool UpVend = false;
            bool UpAcc = false;

            DataTable dtDocDetItm = null;   //Caller Document Detail Items
            DataTable dtDocDetExp = null;   //Caller Document Detail Expenses

            //for Saving
            DataTable dsItems = null;       //working table for MSTItm, MSTItmLoc and MSTItmHis update
            DataTable dsItemsBatch = null;  //working table for MSTItmBatch, MSTItmBatchLog update
            DataTable dtCV = null;          //working table for MSTCon, MSTConHis update
            DataTable dtPost = null;        //working table for Posting GLLog update

            int counterLastID = -999;       //For Updating LastIDCounter (we use a -ve value to indicate that there no need to update the SYSIDCounter table
            int counterPeriod = 0;
            int counterDocGrpKey = 0;
            int counterConKey = 0;
            int counterEMKey = 0;
            string counterGrpStr = string.Empty;

            int OldDocState = objDoc.DocState.Value;
            SYSAttachments objSYSAttachments = null;
            #endregion

            try
            {
                #region get Detail DataTable from hashtable
                switch (objDoc.DocCodeKey)
                {
                    case (int)GEnum.SystemCode.Quotation:
                    case (int)GEnum.SystemCode.Purchase_Plan:
                    case (int)GEnum.SystemCode.Purchase_Request:
                    case (int)GEnum.SystemCode.Sales_Order:
                    case (int)GEnum.SystemCode.Reserve_Order:
                    case (int)GEnum.SystemCode.Purchase_Order:
                    case (int)GEnum.SystemCode.Order_Consignment:
                    case (int)GEnum.SystemCode.Sales_Order_Adjustment:
                    case (int)GEnum.SystemCode.Purchase_Order_Adjustment:
                    case (int)GEnum.SystemCode.Consignment_Order_Adjustment:
                    case (int)GEnum.SystemCode.Delivery_Order:
                    case (int)GEnum.SystemCode.Purchase_Shipment:
                    case (int)GEnum.SystemCode.Purchase_Delivery:
                    case (int)GEnum.SystemCode.Received_Consignment:
                    case (int)GEnum.SystemCode.Packing_List:
                    case (int)GEnum.SystemCode.Consignment_Settlement:
                    case (int)GEnum.SystemCode.Sales_Invoice:
                    case (int)GEnum.SystemCode.Sales_Debit_Note:
                    case (int)GEnum.SystemCode.Sales_Credit_Note:
                    case (int)GEnum.SystemCode.Cash_Sale:
                    case (int)GEnum.SystemCode.Cash_Debit_Note:
                    case (int)GEnum.SystemCode.Cash_Credit_Note:
                    case (int)GEnum.SystemCode.Purchase_Invoice:
                    case (int)GEnum.SystemCode.Purchase_Debit_Note:
                    case (int)GEnum.SystemCode.Purchase_Credit_Note:
                    case (int)GEnum.SystemCode.Contra:
                    case (int)GEnum.SystemCode.Cash_Contra:
                    case (int)GEnum.SystemCode.Inventory_Adjustment:
                    case (int)GEnum.SystemCode.Inventory_Production:
                    case (int)GEnum.SystemCode.Inventory_Transfer:
                    case (int)GEnum.SystemCode.Journal:
                    case (int)GEnum.SystemCode.Deposit:
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Itm, dtDetails, ref dtDocDetItm);
                        break;
                    case (int)GEnum.SystemCode.Issue_Consignment:
                    case (int)GEnum.SystemCode.Return_Consignment:
                    case (int)GEnum.SystemCode.Payment_Received:
                    case (int)GEnum.SystemCode.Cash_Payment_Received:
                    case (int)GEnum.SystemCode.Payment_Issue:
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Itm, dtDetails, ref dtDocDetItm);
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Exp, dtDetails, ref dtDocDetExp);
                        break;
                }
                #endregion

                #region Get process to run in posting
                if (Doc_SetSaveProcess(cn, objDoc, ButtonAction, ApprovalReq, Authorised, ref NewDocState, ref UpType, ref UpItmHis, ref UpStock, ref UpCust, ref UpVend, ref UpAcc) == false)
                    return false;
                else
                {
                    if (MultiProcessDocCode == (int)GEnum.SystemCode.DO_to_IV_Transfer)
                    {
                        //this will prevent process from generating working data which DOIV will not use, the process to block are as follows:
                        //Doc_Item_Prepare(),Doc_ItemBatch_Prepare()
                        UpItmHis = false;
                        UpStock = false;
                    }
                }
                #endregion

                #region Add Posting Lock
                if (ButtonAction != (int)GEnum.DocAction.Delete && objDoc.DocState == (int)GEnum.DocState.New)
                {
                    if (SysLockUtility.AddPostingLock(cn, false, objDoc.GUID, (GEnum.SystemCode)objDoc.DocCodeKey))
                    {
                        postingLockAdded = true;
                    }
                    else
                    {
                        MsgBox.Show(cn, "Another session is in progress, Please try again a few seconds later");
                        return false;
                    }
                }
                #endregion

                #region  Prepare Itm History
                dsItems = Doc_Item_Prepare(cn, objDoc, NewDocState, dtDocDetItm, UpType, UpStock, UpItmHis);
                #endregion

                #region  Prepare Customer History
                dtCV = Doc_CV_Prepare(cn, objDoc, dtDocDetItm, dtSvrData, UpType).Copy();
                #endregion

                #region Get NewDocID OR Look for Duplicate DocID for DocState(NEW) / check duplicate DocID for DocState(EDIT)
                if (ButtonAction != (int)GEnum.DocAction.Delete)
                {
                    if (objDoc.DocState == (int)GEnum.DocState.New)
                    {
                        if (!GFunc.IsNE(objDoc.DocID)) /* added by YST on 2024-12-05 */
                        {
                            objDoc.DocID = objDoc.DocID.Replace(Environment.NewLine, "").Trim();
                        }

                        if (GFunc.IsNE(objDoc.DocID.Trim()))
                        {
                            #region Generate AutoID

                            #region Get docConKey
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Quotation:
                                case (int)GEnum.SystemCode.Sales_Order:
                                case (int)GEnum.SystemCode.Reserve_Order:
                                case (int)GEnum.SystemCode.Sales_Order_Adjustment:
                                case (int)GEnum.SystemCode.Delivery_Order:
                                case (int)GEnum.SystemCode.Packing_List:
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Sales_Adjustment:
                                case (int)GEnum.SystemCode.Payment_Received:
                                case (int)GEnum.SystemCode.Contra:
                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Adjustment:
                                case (int)GEnum.SystemCode.Cash_Payment_Received:
                                case (int)GEnum.SystemCode.Cash_Contra:
                                case (int)GEnum.SystemCode.Purchase_Plan:
                                case (int)GEnum.SystemCode.Purchase_Order:
                                case (int)GEnum.SystemCode.Purchase_Order_Adjustment:
                                case (int)GEnum.SystemCode.Purchase_Shipment:
                                case (int)GEnum.SystemCode.Purchase_Delivery:
                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                case (int)GEnum.SystemCode.Payment_Issue:
                                case (int)GEnum.SystemCode.Issue_Consignment:
                                case (int)GEnum.SystemCode.Return_Consignment:
                                case (int)GEnum.SystemCode.Order_Consignment:
                                case (int)GEnum.SystemCode.Consignment_Order_Adjustment:
                                case (int)GEnum.SystemCode.Received_Consignment:
                                case (int)GEnum.SystemCode.Consignment_Settlement:
                                    docConKey = GFunc.NEInt((int)GFunc.GetIntPropertyValue("DocConKey", objDoc), 0);
                                    break;
                            }
                            #endregion

                            #region Get docGrpKey
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Quotation:
                                case (int)GEnum.SystemCode.Sales_Order:
                                case (int)GEnum.SystemCode.Reserve_Order:
                                case (int)GEnum.SystemCode.Sales_Order_Adjustment:
                                case (int)GEnum.SystemCode.Delivery_Order:
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Sales_Adjustment:
                                case (int)GEnum.SystemCode.Payment_Received:
                                case (int)GEnum.SystemCode.Contra:
                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Adjustment:
                                case (int)GEnum.SystemCode.Cash_Payment_Received:
                                case (int)GEnum.SystemCode.Cash_Contra:
                                case (int)GEnum.SystemCode.Purchase_Plan:
                                case (int)GEnum.SystemCode.Purchase_Request:
                                case (int)GEnum.SystemCode.Purchase_Order:
                                case (int)GEnum.SystemCode.Purchase_Order_Adjustment:
                                case (int)GEnum.SystemCode.Purchase_Shipment:
                                case (int)GEnum.SystemCode.Purchase_Delivery:
                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                case (int)GEnum.SystemCode.Payment_Issue:
                                case (int)GEnum.SystemCode.Inventory_Adjustment:
                                case (int)GEnum.SystemCode.Inventory_Production:
                                case (int)GEnum.SystemCode.Inventory_Transfer:
                                case (int)GEnum.SystemCode.Issue_Consignment:
                                case (int)GEnum.SystemCode.Return_Consignment:
                                case (int)GEnum.SystemCode.Order_Consignment:
                                case (int)GEnum.SystemCode.Consignment_Order_Adjustment:
                                case (int)GEnum.SystemCode.Received_Consignment:
                                case (int)GEnum.SystemCode.Journal:
                                case (int)GEnum.SystemCode.Deposit:
                                case (int)GEnum.SystemCode.Bank_Revaluation:
                                    docGrpKey = GFunc.NEInt((int)GFunc.GetIntPropertyValue("DocGrpKey", objDoc), 0);
                                    break;
                            }

                            #endregion

                            //Added by YST on 2021/12/15 to follow like another Doc_Posting Function 
                            int JobKey = 0;
                            #region Get docJobKey
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Quotation:
                                case (int)GEnum.SystemCode.Sales_Order:
                                case (int)GEnum.SystemCode.Reserve_Order:
                                case (int)GEnum.SystemCode.Delivery_Order:
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                    DataRow[] drs = dtDocDetItm.Select("ItmJobKey<>0");
                                    if (drs.Length > 0)
                                    {
                                        JobKey = GFunc.NEInt(drs[0]["ItmJobKey"], 0);
                                    }
                                    break;
                            }
                            #endregion                            

                            //if (SysIDCounterUtility.Get(cn, out DocAutoID, out counterGrpStr, out counterLastID, out counterPeriod, out counterDocGrpKey, out counterConKey, out counterEMKey, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.DocTypeNm, docGrpKey, docConKey, objDoc.DocEmKey, objDoc.DocDate.Value))
                            if (SysIDCounterUtility.Get(cn, out DocAutoID, out counterGrpStr, out counterLastID, out counterPeriod, out counterDocGrpKey, out counterConKey, out counterEMKey, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.DocTypeNm, docGrpKey, docConKey, JobKey, objDoc.DocDate.Value))
                                    objDoc.DocID = DocAutoID;
                            else
                                return false;

                            #endregion
                        }
                        else
                        {
                            #region Check Duplicate DocID
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Purchase_Shipment:
                                case (int)GEnum.SystemCode.Purchase_Delivery:
                                    // for APBL,APDN,APCN,APPD must check with ConKey + DocID
                                    docConKey = GFunc.NEInt((int)GFunc.GetIntPropertyValue("DocConKey", objDoc), 0);
                                    if (SysIDCounterUtility.DuplicateFound(cn, objDoc.DocID, (GEnum.SystemCode)objDoc.DocCodeKey, docConKey, 0, 0))
                                    {
                                        MsgBox.Show(cn, "DocID" + MsgID.Validation.DuplicateRecord);
                                        return false;
                                    }
                                    break;

                                default:
                                    if (SysIDCounterUtility.DuplicateFound(cn, objDoc.DocID, (GEnum.SystemCode)objDoc.DocCodeKey, (int)objDoc.DocKey, 0, 0, (short)0))
                                    {
                                        MsgBox.Show(cn, "DocID" + MsgID.Validation.DuplicateRecord);
                                        return false;
                                    }
                                    break;
                            }
                            #endregion
                        }
                    }
                    else
                    {
                        if (GFunc.IsNE(objDoc.DocID.Trim()))
                        {
                            MsgBox.Show(cn, "Document Number" + MsgID.Validation.IsRequire);
                            return false;
                        }
                        else
                        {
                            #region Check Duplicate DocID
                            // for APBL,APDN,APCN,APPD must check with ConKey + DocID
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Purchase_Shipment:
                                case (int)GEnum.SystemCode.Purchase_Delivery:
                                    docConKey = GFunc.NEInt(GFunc.GetIntPropertyValue("DocConKey", objDoc), 0);//Ask Mic
                                    if (SysIDCounterUtility.DuplicateFound(cn, objDoc.DocID, (GEnum.SystemCode)objDoc.DocCodeKey, GFunc.NEInt(objDoc.DocKey, 0), docConKey, 0, 0))
                                    {
                                        MsgBox.Show(cn, "DocID" + MsgID.Validation.DuplicateRecord);
                                        return false;
                                    }
                                    break;

                                default:

                                    if (SysIDCounterUtility.DuplicateFound(cn, objDoc.DocID, (GEnum.SystemCode)objDoc.DocCodeKey, GFunc.NEInt(objDoc.DocKey, 0), 0, 0, 0))
                                    {
                                        MsgBox.Show(cn, "DocID" + MsgID.Validation.DuplicateRecord);
                                        return false;
                                    }
                                    break;
                            }
                            #endregion
                        }
                    }
                }
                #endregion

                #region Prepare Posting
                dtPost = Doc_Posting_Prepare(cn, objDoc, ButtonAction, dtDetails, DocAutoID);
                #endregion

                #region Check detail ItmQty match with child detail ItmBatchQty and saving new batch into Mst_ItmBatch
                if (BatchQty_Check(cn, objDoc, dtDocDetItm, false, ButtonAction) == false)
                {
                    MsgBox.Show(cn, MsgID.Common.ValidationFail + "%Batch Qty");
                    return false;
                }
                #endregion

                #region  Prepare Itm Batch History
                switch (objDoc.DocCodeKey)
                {
                    case (int)GEnum.SystemCode.Delivery_Order:
                    case (int)GEnum.SystemCode.Sales_Invoice:
                    case (int)GEnum.SystemCode.Sales_Credit_Note:
                    case (int)GEnum.SystemCode.Sales_Debit_Note:
                    case (int)GEnum.SystemCode.Cash_Sale:
                    case (int)GEnum.SystemCode.Cash_Credit_Note:
                    case (int)GEnum.SystemCode.Cash_Debit_Note:
                    case (int)GEnum.SystemCode.Purchase_Shipment:
                    case (int)GEnum.SystemCode.Purchase_Delivery:
                    case (int)GEnum.SystemCode.Purchase_Invoice:
                    case (int)GEnum.SystemCode.Purchase_Credit_Note:
                    case (int)GEnum.SystemCode.Purchase_Debit_Note:
                    case (int)GEnum.SystemCode.Inventory_Adjustment:
                    case (int)GEnum.SystemCode.Inventory_Production:
                    case (int)GEnum.SystemCode.Inventory_Transfer:
                    case (int)GEnum.SystemCode.Issue_Consignment:
                    case (int)GEnum.SystemCode.Return_Consignment:
                        dsItemsBatch = Doc_ItemBatch_Prepare(cn, objDoc, NewDocState, dtDocDetItm, UpType, UpStock, UpItmHis, out cancelProcess);
                        if (cancelProcess)
                            return false;
                        break;

                    default:
                        dsItemsBatch = new DataTable();    //need to have an empty dataset as it is required in the Doc_Update() later
                        break;
                }
                #endregion

                //Perform actual posting to server data
                if (!Doc_Update(cn, objDoc, dtDetails, dsItems, dsItemsBatch, dtCV, dtPost, ButtonAction, NewDocState, UpType, UpItmHis, UpStock, UpCust, UpVend, UpAcc, objDoc.DocID, counterGrpStr, counterLastID, counterPeriod, counterDocGrpKey, counterConKey, counterEMKey, MultiProcessDocCode))
                    throw new Exception("Posting failed.");

                if (!((objDoc.DocCodeKey == (int)GEnum.SystemCode.Delivery_Order
                           || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order
                           || objDoc.DocCodeKey == (int)GEnum.SystemCode.Cash_Sale
                           || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Invoice)
                           && SysOptionUtility.HasDMASLink))//Added by May on 22 Nov 2021.. if Link to DMAS, DO will save once files are attached
                {
                    DocComUtility.DocDetail_Get(GEnum.Details.Doc_Attachment, dtDetails, ref objSYSAttachments);
                    if (!AttachmentSave(cn, objSYSAttachments, (GEnum.SystemCode)objDoc.DocCodeKey,objDoc.DocKey))
                        return false;
                }

                //Update objDoc(DocID,DocState) with newDocID and newDocState
                if (OldDocState == (int)GEnum.DocState.New)
                {
                    if (objDoc.DocID == string.Empty && DocAutoID != string.Empty)
                        objDoc.DocID = DocAutoID;
                    objDoc.DocState = NewDocState;
                    SysLockUtility.AddLock(cn, true, objDoc.GUID, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.DocKey);
                }

                if ( SysOptionUtility.DatabaseBranchCode == "BHM" && 
                    (int)ButtonAction == (int)GEnum.DocAction.Post &&
                    (objDoc.DocCodeKey == (int)GEnum.SystemCode.Quotation ||
                    objDoc.DocCodeKey == (int)GEnum.SystemCode.Reserve_Order ||
                    objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order))
                {
                    /* added by YST on 2022/06/30 to bind DocSate that updated in SQL_Save funtion */
                    List<SqlParameter> lstParam = new List<SqlParameter>();
                    lstParam.Add(new SqlParameter("@DocKey", objDoc.DocKey));
                    lstParam.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                    string UpdatedDocState = GFunc.ExecuteScalar(cn, "DocState_Get", lstParam);
                    objDoc.DocState = Convert.ToInt16(UpdatedDocState);
                }              

            }
            catch (TAException taex)
            {
                throw Error(taex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
            finally
            {
                dtDocDetItm = null;
                dsItems = null;
                dtCV = null;
                dtDocDetExp = null;
                dtPost = null;
                if (postingLockAdded)
                    SysLockUtility.RemoveLock(cn, true, (int)option, (GEnum.SystemCode)objDoc.DocCodeKey, objDoc.GUID, dataKey, inProgressKey);
            }
            return true;
        }//Completed

        private static bool Doc_SetSaveProcess(Document objDoc, int ButtonAction, bool ApprovalReq, bool Authorised, ref int NewDocState, ref string UpType, ref bool UpItmHis, ref bool UpStock, ref bool UpCust, ref bool UpVend, ref bool UpAcc)
        {
            string approvalReq = "Anything";
            string authorized = "Anything";
            try
            {
                GEnum.DocAction bAction = (GEnum.DocAction)int.Parse(ButtonAction.ToString());

                //The below code was modified to set the parameters for No approval required and No authorisation required conditions
                if (ApprovalReq)
                    approvalReq = "Yes";
                else
                    approvalReq = "No";

                //if (Authorised)
                //    authorized = "Yes";
                //else
                //    authorized = "No";

                List<SqlParameter> parmList = new List<SqlParameter>();
                parmList.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                parmList.Add(new SqlParameter("@Action", bAction.ToString()));
                parmList.Add(new SqlParameter("@OldState", objDoc.DocState));
                parmList.Add(new SqlParameter("@ApprovalReq", approvalReq));
                parmList.Add(new SqlParameter("@AuthorisedReq", authorized));
                DataTable dt = GFunc.ExecuteProc("Doc_GetSaveProcessSetting", parmList);

                if (dt.Rows.Count > 0)
                {
                    NewDocState = GFunc.NEInt(dt.Rows[0]["NewState"], 0);
                    UpType = GFunc.NEStr(dt.Rows[0]["UpType"], string.Empty);
                    UpItmHis = (bool)dt.Rows[0]["UpItmHis"];
                    //Mic -- Non-Track Document Type
                    //Although normal Sales Order/Purchase Order Update to ItmHistory table, here we'll neglect for Non-tracking Doctype
                    if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order || objDoc.DocCodeKey == (int)GEnum.SystemCode.Purchase_Order)
                    {
                        if (objDoc.DocType == 200 /* Non Tracking Tax Exclusive */ || objDoc.DocType == 210 /* Non Tracking Tax Inclusive */) //If it is non-tracking type
                        {
                            UpItmHis = false;
                        }
                    }

                    ////Although normal Reserve Order/Sales Order/ Delivery Order/ Update to ItmHistory table, here we'll neglect if document is in pending approval state.
                    //if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Reserve_Order || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order || objDoc.DocCodeKey == (int)GEnum.SystemCode.Delivery_Order)
                    //{
                    //    if (GVar.CrLimitApprovalReq == true )
                    //    {
                    //        UpItmHis = false;
                    //        UpStock = false;
                    //    }
                    //}
                    UpStock = (bool)dt.Rows[0]["UpStock"];
                    UpCust = (bool)dt.Rows[0]["UpCust"];
                    UpVend = (bool)dt.Rows[0]["UpVend"];
                    UpAcc = (bool)dt.Rows[0]["UpAcc"];

                    if(!ApprovalReq)
                    {
                        try
                        {
                            objDoc.DocStatus = ((GEnum.DocState)NewDocState).ToString();
                        }
                        catch
                        {

                        }
                    }
                }
                else
                {
                    if (Authorised)
                    {
                        MsgBox.Show("This process is not allowed");
                    }
                    else
                    {
                        MsgBox.Show("You do not have the permission to perform this function");
                    }
                    return false;
                }

               
                return true;
            }
            catch (TAException taex)
            {
                throw Error(taex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
        }//Completed
        private static bool Doc_SetSaveProcess(SqlConnection cn, Document objDoc, int ButtonAction, bool ApprovalReq, bool Authorised, ref int NewDocState, ref string UpType, ref bool UpItmHis, ref bool UpStock, ref bool UpCust, ref bool UpVend, ref bool UpAcc)
        {
            string approvalReq = "Anything";
            string authorized = "No";
            try
            {
                GEnum.DocAction bAction = (GEnum.DocAction)int.Parse(ButtonAction.ToString());

                //The below code was modified to set the parameters for No approval required and No authorisation required conditions
                if (ApprovalReq)
                    approvalReq = "Yes";
                else
                    approvalReq = "No";

                if (Authorised)
                    authorized = "Yes";
                else
                    authorized = "No";

                List<SqlParameter> parmList = new List<SqlParameter>();
                parmList.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                parmList.Add(new SqlParameter("@Action", bAction.ToString()));
                parmList.Add(new SqlParameter("@OldState", objDoc.DocState));
                parmList.Add(new SqlParameter("@ApprovalReq", approvalReq));
                parmList.Add(new SqlParameter("@AuthorisedReq", authorized));
                DataTable dt = GFunc.ExecuteProc(cn, "Doc_GetSaveProcessSetting", parmList);

                if (dt.Rows.Count > 0)
                {
                    NewDocState = GFunc.NEInt(dt.Rows[0]["NewState"], 0);
