                                                dr["ItmQtyAdj"] = GFunc.RndC(TranSign * (GFunc.NEDec(rowAdj["ItmQty"], 0) - GFunc.NEDec(rowAdj["ItmQtyAdj"], 0)) * docSign * (decimal)rowAdj["ItmConRate"], GVar.RndDecs.Qtypt);
                                                dr["ItmAmt"] = GFunc.RndC(TranSign * (decimal)rowAdj["ItmAmtH"] * docSign, GVar.RndDecs.Amtpt);// Not ready; This value is incorrect but currently it is not used in the enquiry screen
