                                                dr["TransQty"] = GFunc.RndC(TranSign * GFunc.NEDec(rowAdj["ItmQty"], 0) * docSign * GFunc.NEDec(rowAdj["ItmConRate"], 0), GVar.RndDecs.Qtypt);
                                                dr["ItmQtyAdj"] = GFunc.RndC(TranSign * GFunc.NEDec(rowAdj["ItmQtyAdj"], 0) * docSign * GFunc.NEDec(rowAdj["ItmConRate"], 0), GVar.RndDecs.Qtypt);
                                                dr["ItmAmt"] = GFunc.RndC(TranSign * GFunc.NEDec(rowAdj["ItmAmtH"], 0) * docSign, GVar.RndDecs.Amtpt);
                                                dtTrans.Rows.Add(dr);
                                            }
                                            else
                                            {
                                                //Reverse Original Transaction in ItmHis
                                                dr = dtTrans.NewRow();
                                                dr["ItmKey"] = (int)rowAdj["ItmKey"];
                                                dr["LocKey"] = GFunc.NEInt(rowAdj["LocKey"], 0);
