                                                    if (LinkKeys.Split(",".ToCharArray()).Contains(dc.ColumnName))
                                                    {
                                                        drH[dc.ColumnName] = rowLocal[dc.ColumnName];
                                                    }
                                                }
                                                dtTrans.Rows.Add(drH);
