                                                //  drE["Period"] = GFunc.NEInt(DateTime.Parse(rowLocal["ItmPrmDate"].ToString()).ToString("yyyyMM"), 0);
                                                if (GFunc.IsNE(rowLocal["ItmPrmDate"]))
                                                    drE["Period"] = 0;
                                                else
