                                                //drE["LineType"] = 1000;
                                                drE["LineType"] = lineTypeCurr; // Setting it to 1000 or 1100
                                                drE["LocKey"] = (int)rowLocal["ItmLocKey"];
                                                //drE["TransQty"] = GFunc.RndC(TranSign * GFunc.NEDec(rowLocal["ItmQty"], 0)  * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                drE["TransQty"] = GFunc.RndC(TranSign * (GFunc.NEDec(rowLocal["ItmQty"], 0) - GFunc.NEDec(rowLocal["DSQty"], 0)) * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);

                                                drE["ItmQtyAdj"] = GFunc.RndC(TranSign * GFunc.NEDec(rowLocal["ItmQtyAdj"], 0) * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                //   drE["ItmAmt"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmAmtH"] * docSign, GVar.RndDecs.Amtpt);
                                                drE["ItmAmt"] = GFunc.RndC(TranSign *
                                                   (GFunc.NEDec(rowLocal["ItmQty"], 0) - GFunc.NEDec(rowLocal["DSQty"], 0)) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc) *
                                                     GFunc.NEDec(rowLocal["ItmPriceUser"], 0) * docSign, GVar.RndDecs.Amtpt);
                                                foreach (DataColumn dc in dtDocDetItmCopy.Columns)
                                                {
                                                    if (LinkKeys.Split(",".ToCharArray()).Contains(dc.ColumnName))
                                                    {
                                                        drE[dc.ColumnName] = rowLocal[dc.ColumnName];
                                                    }
                                                }
                                                dtTrans.Rows.Add(drE);
                                            }
                                            break;
                                        #endregion

                                        case (int)GEnum.SystemCode.Order_Consignment:

                                            #region Prepare dtTran
                                            if (upItmHis)
                                            {
                                                DataRow drE = dtTrans.NewRow();
                                                drE["ItmKey"] = (int)rowLocal["ItmKey"];
                                                if (GFunc.IsNE(rowLocal["ItmPrmDate"]))
                                                    drE["Period"] = 0;
                                                else
                                                    drE["Period"] = GFunc.NEInt(Convert.ToDateTime(rowLocal["ItmPrmDate"]).ToString("yyyyMM"), 0);
                                                drE["LineType"] = 1000;
                                                drE["LocKey"] = (int)rowLocal["ItmLocKey"];
                                                drE["TransQty"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmQty"] * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                drE["ItmQtyAdj"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmQtyAdj"] * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                drE["ItmAmt"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmAmtH"] * docSign, GVar.RndDecs.Amtpt);
                                                foreach (DataColumn dc in dtDocDetItmCopy.Columns)
                                                {
                                                    if (LinkKeys.Split(",".ToCharArray()).Contains(dc.ColumnName))
                                                    {
                                                        drE[dc.ColumnName] = rowLocal[dc.ColumnName];
                                                    }
                                                }
                                                dtTrans.Rows.Add(drE);
                                            }
                                            break;
                                        #endregion

                                        case (int)GEnum.SystemCode.Received_Consignment:

                                            #region Prepare dtTran
                                            DataRow drF = null;
                                            drF = dtTrans.NewRow();
                                            drF["ItmKey"] = (int)rowLocal["ItmKey"];
                                            drF["Period"] = period;
                                            drF["LineType"] = 1000;
                                            drF["LocKey"] = (int)rowLocal["ItmLocKey"];
                                            drF["TransQty"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmQty"] * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                            drF["ItmAmt"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmAmtH"] * docSign, GVar.RndDecs.Amtpt);
                                            foreach (DataColumn dc in dtDocDetItmCopy.Columns)
                                            {
                                                if (LinkKeys.Split(",".ToCharArray()).Contains(dc.ColumnName))
                                                {
                                                    drF[dc.ColumnName] = rowLocal[dc.ColumnName];
                                                }
                                            }
                                            dtTrans.Rows.Add(drF);
                                            break;
                                        #endregion

                                        case (int)GEnum.SystemCode.Delivery_Order:
                                        case (int)GEnum.SystemCode.Sales_Invoice:
                                        case (int)GEnum.SystemCode.Sales_Debit_Note:
                                        case (int)GEnum.SystemCode.Sales_Credit_Note:
                                        case (int)GEnum.SystemCode.Cash_Sale:
                                        case (int)GEnum.SystemCode.Cash_Debit_Note:
                                        case (int)GEnum.SystemCode.Cash_Credit_Note:
                                        case (int)GEnum.SystemCode.Purchase_Shipment:
                                        case (int)GEnum.SystemCode.Purchase_Delivery:
                                        case (int)GEnum.SystemCode.Purchase_Invoice:
                                        case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                        case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                            #region Prepare dtTran
                                            DataRow drH = null;
                                            if ((int)rowLocal["LineType"] == 1000)
                                            {
                                                drH = dtTrans.NewRow();
                                                drH["ItmKey"] = (int)rowLocal["ItmKey"];
                                                drH["Period"] = period;
                                                drH["LineType"] = 1000;
                                                drH["LocKey"] = (int)rowLocal["ItmLocKey"];
                                                //   drH["TransQty"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmQty"] * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                drH["TransQty"] = GFunc.RndC(TranSign * (GFunc.NEDec(rowLocal["ItmQty"], 0) - GFunc.NEDec(rowLocal["DSQty"], 0)) * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);

                                                //  drH["ItmAmt"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmAmtH"] * docSign, GVar.RndDecs.Amtpt);
                                                drH["ItmAmt"] = GFunc.RndC(TranSign *
                                                   (GFunc.NEDec(rowLocal["ItmQty"], 0) - GFunc.NEDec(rowLocal["DSQty"], 0)) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc) *
                                                     GFunc.NEDec(rowLocal["ItmPriceUser"], 0) * docSign, GVar.RndDecs.Amtpt);
                                                foreach (DataColumn dc in dtDocDetItmCopy.Columns)
                                                {
                                                    if (LinkKeys.Split(",".ToCharArray()).Contains(dc.ColumnName))
                                                    {
                                                        drH[dc.ColumnName] = rowLocal[dc.ColumnName];
                                                    }
                                                }
                                                dtTrans.Rows.Add(drH);
                                            }
                                            else if ((int)rowLocal["LineType"] == 1100)//Assembly
                                            {
                                                drH = dtTrans.NewRow();
                                                drH["ItmKey"] = (int)rowLocal["ItmKey"];
                                                drH["Period"] = period;
                                                drH["LineType"] = 1100;
                                                drH["LocKey"] = (int)rowLocal["ItmLocKey"];
                                                //drH["TransQty"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmQty"] * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                drH["TransQty"] = GFunc.RndC(TranSign * (GFunc.NEDec(rowLocal["ItmQty"], 0) - GFunc.NEDec(rowLocal["DSQty"], 0)) * docSign * (decimal)rowLocal["ItmConRate"], GVar.RndDecs.Qtypt);
                                                //drH["ItmAmt"] = GFunc.RndC(TranSign * (decimal)rowLocal["ItmAmtH"] * docSign, GVar.RndDecs.Amtpt);
                                                drH["ItmAmt"] = GFunc.RndC(TranSign *
                                                  (GFunc.NEDec(rowLocal["ItmQty"], 0) - GFunc.NEDec(rowLocal["DSQty"], 0)) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc) *
                                                    GFunc.NEDec(rowLocal["ItmPriceUser"], 0) * docSign, GVar.RndDecs.Amtpt);
                                                foreach (DataColumn dc in dtDocDetItmCopy.Columns)
                                                {
                                                    if (LinkKeys.Split(",".ToCharArray()).Contains(dc.ColumnName))
                                                    {
                                                        drH[dc.ColumnName] = rowLocal[dc.ColumnName];
                                                    }
                                                }
                                                dtTrans.Rows.Add(drH);
                                            }
                                            break;
                                        #endregion

                                        default:
                                            return null;
                                    }
                                }
                            }
                            #endregion
                        }
                        #endregion

                        #region Preparing for insufficient stock level and return datatable for dtItmHis

                        DataTable dtOutOfStockList = new DataTable("dtLoc");    //Use to display list of outof stock items
                        bool StockLevelOutOfStockOccurred = false;
                        xmlPara = GFunc.ConvertDataTableToXML(dtTrans);
                        paraList = new List<SqlParameter>();
                        paraList.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                        paraList.Add(new SqlParameter("@DocKey", objDoc.DocKey));
                        paraList.Add(new SqlParameter("@NewDocState", NewDocState));
                        paraList.Add(new SqlParameter("@UpStock", upStock));
                        paraList.Add(new SqlParameter("@UpType", upType));
                        paraList.Add(new SqlParameter("@xmlTrans", xmlPara));
                        SqlParameter para = new SqlParameter();
                        int bNotEnough = 0;
                        para.ParameterName = "@IsNoEnoughQty";
                        para.Value = bNotEnough;
                        para.Direction = ParameterDirection.Output;
                        paraList.Add(para);
                        DataSet dsTrans = GFunc.ExecuteProcDataSet(cn, "[Doc_PrepareItmHis_Get]", paraList);
                        bNotEnough = (int)para.Value;
                        #endregion

                        dtItmHis = dsTrans.Tables[(int)ItmTableIndex.ItemHis].Copy();
                        return dtItmHis;
                    default:
                        return new DataTable();
                }
            }
            catch (TAException taex)
            {
                throw taex;
            }
            catch (Exception ex)
            {
                throw ex;
            }
            finally
            {
                dtItmHis = null;
                dtDocDetItmCopy = null;
            }
        }//Completed      
        private static DataTable Doc_CV_Prepare(Document objDoc, DataTable dtDocDetItm, DataTable dtSvrData, string upType, out bool cancelProcess, ref bool userContinueCLExceeded, ref bool userContinueTermExceeded, bool firstTime,int ButtonAction)
        {
            try
            {
                #region Local Variables

                //Process Variables
                int limitControlOpt = 0;
                bool runCheck = false;
                bool runCreditLimitCheck = false;
                bool runCreditLimitControl = false;
                bool runExceedTermCheck = false;
                bool runExceedTermControl = false;
                bool runCheckdocApplyGainAmt = false;
                bool runCalForPayment = false;
                decimal exceedAmt = 0;
                SqlCommand cm = null;

                //Common Document variables
                int docCodeKey = 0;
                short docSign = 0;

                //Obj Variables
                int docConKey = 0;
                int docPeriod = 0;
                int docGrpKey = 0;
                int docCurrKey = 0;
                decimal docGrand = 0;
                decimal docHome = 0;
               // decimal docApplyGainAmt = 0;
               // decimal docPaymentDetAmtH = 0;

                //Server Variables
                int svrTransSign = -1;
                int svrdocConKey = 0;
                int svrdocPeriod = 0;
                int svrdocGrpKey = 0;
                int svrdocCurrKey = 0;
                decimal svrdocGrand = 0;
                decimal svrdocHome = 0;
              //  decimal svrdocApplyGainAmt = 0;
               // decimal svrdocPaymentDetAmtH = 0;

                //Variable for Balance Calculation
              //  decimal? CRAmt = 0;
               // decimal? CHAmt = 0;
               // decimal? VAmt = 0;
                decimal? FCR = 0;
                decimal? FCH = 0;
                decimal? FV = 0;
                decimal? HCR = 0;
                decimal? HCH = 0;
                decimal? HV = 0;
                decimal? FAmt = 0;
                decimal? HAmt = 0;
                
                decimal? FNT = 0;
                decimal? HNT = 0;

                DataTable dtSvrConHis = null;
                #endregion

                cancelProcess = false;
                switch (objDoc.DocCodeKey)
                {
                    case (int)GEnum.SystemCode.Quotation:
                    case (int)GEnum.SystemCode.Sales_Order:
                    case (int)GEnum.SystemCode.Reserve_Order:
                    case (int)GEnum.SystemCode.Delivery_Order:
                    case (int)GEnum.SystemCode.Sales_Invoice:
                    case (int)GEnum.SystemCode.Sales_Debit_Note:
                    case (int)GEnum.SystemCode.Sales_Credit_Note:
                    case (int)GEnum.SystemCode.Sales_Adjustment:
                    case (int)GEnum.SystemCode.Payment_Received:
                    case (int)GEnum.SystemCode.Contra:
                    case (int)GEnum.SystemCode.Cash_Sale:
                    case (int)GEnum.SystemCode.Cash_Debit_Note:
                    case (int)GEnum.SystemCode.Cash_Credit_Note:
                    case (int)GEnum.SystemCode.Cash_Adjustment:
                    case (int)GEnum.SystemCode.Cash_Payment_Received:
                    case (int)GEnum.SystemCode.Cash_Contra:
                    case (int)GEnum.SystemCode.Purchase_Order:
                    case (int)GEnum.SystemCode.Purchase_Invoice:
                    case (int)GEnum.SystemCode.Purchase_Debit_Note:
                    case (int)GEnum.SystemCode.Purchase_Credit_Note:
                    case (int)GEnum.SystemCode.Purchase_Adjustment:
                    case (int)GEnum.SystemCode.Payment_Issue:

                        #region Creating dtConHis table structure
                        DataTable dtConHis = new DataTable("ConHistory");
                        dtConHis.Columns.Add("ConKey", typeof(int));
                        dtConHis.Columns.Add("Period", typeof(int));
                        dtConHis.Columns.Add("DocDC", typeof(int));
                        dtConHis.Columns.Add("DocGrpKey", typeof(int));
                        dtConHis.Columns.Add("DocCurrKey", typeof(int));
                        //dtConHis.Columns.Add("CRAmt", typeof(decimal));
                        //dtConHis.Columns.Add("ChAmt", typeof(decimal));
                        //dtConHis.Columns.Add("VAmt", typeof(decimal));
                        dtConHis.Columns.Add("CrAmtF", typeof(decimal));
                        dtConHis.Columns.Add("CrAmtH", typeof(decimal));
                        dtConHis.Columns.Add("ChAmtF", typeof(decimal));
                        dtConHis.Columns.Add("ChAmtH", typeof(decimal));
                        dtConHis.Columns.Add("VAmtF", typeof(decimal));
                        dtConHis.Columns.Add("VAmtH", typeof(decimal));
                        dtConHis.Columns.Add("NTAmtF", typeof(decimal));
                        dtConHis.Columns.Add("NTAmtH", typeof(decimal));

                        //set default to zero
                        foreach (DataColumn col in dtConHis.Columns)
                        {
                            col.DefaultValue = 0;
                        }

                        #endregion

                        #region set check condition by doccodekey
                        switch (objDoc.DocCodeKey)
                        {
                            case (int)GEnum.SystemCode.Quotation:                            
                            case (int)GEnum.SystemCode.Reserve_Order:                            
                            case (int)GEnum.SystemCode.Sales_Order:
                            case (int)GEnum.SystemCode.Delivery_Order:
                            case (int)GEnum.SystemCode.Sales_Invoice:
                            case (int)GEnum.SystemCode.Sales_Debit_Note:
                                if (GFunc.NEStr(objDoc.DocStatus, "").ToLower() != "draft")
                                    runCheck = true;
                                break;

                            case (int)GEnum.SystemCode.Sales_Credit_Note:
                                runCheckdocApplyGainAmt = true;
                                runCheck = true;
                                break;

                            case (int)GEnum.SystemCode.Purchase_Credit_Note:
                            case (int)GEnum.SystemCode.Cash_Credit_Note:
                                runCheckdocApplyGainAmt = true;
                                break;

                            case (int)GEnum.SystemCode.Cash_Sale:
                            case (int)GEnum.SystemCode.Cash_Debit_Note:
                            case (int)GEnum.SystemCode.Purchase_Invoice:
                            case (int)GEnum.SystemCode.Purchase_Debit_Note:
                            case (int)GEnum.SystemCode.Sales_Adjustment:
                            case (int)GEnum.SystemCode.Cash_Adjustment:
                            case (int)GEnum.SystemCode.Purchase_Adjustment:
                                break;

                            case (int)GEnum.SystemCode.Payment_Received:
                            case (int)GEnum.SystemCode.Cash_Payment_Received:
                            case (int)GEnum.SystemCode.Payment_Issue:
                            case (int)GEnum.SystemCode.Cash_Contra:
                            case (int)GEnum.SystemCode.Contra:

                                runCalForPayment = true;

                                //get server payment detail DiscountH and GainLossAmtH
                                List<SqlParameter> parmList = new List<SqlParameter>();
                                parmList.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                                parmList.Add(new SqlParameter("@DocKey", objDoc.DocKey));
                                dtSvrConHis = GFunc.ExecuteProc("Doc_PrepareConHis_Get", parmList);
                                break;

                            default:
                                cancelProcess = false;
                                return dtConHis;
                        }
                        #endregion

                        #region Get obj and server data
                        docCodeKey = (int)objDoc.DocCodeKey;
                        docSign = (short)objDoc.DocSign.Value;

                        //Obj Calculation
                        docConKey = GFunc.NEInt((int)GFunc.GetIntPropertyValue("DocConKey", objDoc), 0);
                        docPeriod = Convert.ToInt32(GFunc.NEDateTime(objDoc.DocDate, DateTime.Today).ToString("yyyyMM"));
                        docGrpKey = (int)GFunc.GetIntPropertyValue("DocGrpKey", objDoc);
                        docCurrKey = (int)GFunc.GetIntPropertyValue("DocCurrKey", objDoc);

                        if (runCalForPayment && (objDoc.DocCodeKey != (int)GEnum.SystemCode.Cash_Contra && objDoc.DocCodeKey != (int)GEnum.SystemCode.Contra))
                        {
                            // docGrand = (decimal)GFunc.GetDecimalPropertyValue("DocApplyAmtF", objDoc);
                            //docHome = (decimal)GFunc.GetDecimalPropertyValue("DocApplyAmtH", objDoc) + docPaymentDetAmtH;
                            docGrand =GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtF)", "LinkDocTypeNm not like 'Non-Trade%'"),0);
                            docHome = GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtH)", "LinkDocTypeNm not like 'Non-Trade%'"),0);
                        }
                        else
                        {
                            docGrand = (decimal)GFunc.GetDecimalPropertyValue("DocGrand", objDoc);
                            docHome = (decimal)GFunc.GetDecimalPropertyValue("DocHome", objDoc);
                        }

                        if (runCheckdocApplyGainAmt)
                            docHome = docHome + GFunc.NEDec((decimal)GFunc.GetDecimalPropertyValue("DocApplyGainAmt", objDoc), 0);

                        //Server Calculaton
                        if (dtSvrData.Rows.Count > 0)
                        {
                            svrdocConKey = (int)dtSvrData.Rows[0]["DocConKey"];
                            svrdocPeriod = Convert.ToInt32(GFunc.NEDateTime(dtSvrData.Rows[0]["DocDate"], DateTime.Today).ToString("yyyyMM"));
                            svrdocGrpKey = (int)dtSvrData.Rows[0]["DocGrpKey"];
                            svrdocCurrKey = (int)dtSvrData.Rows[0]["DocCurrKey"];

                            if (runCalForPayment && (objDoc.DocCodeKey != (int)GEnum.SystemCode.Cash_Contra && objDoc.DocCodeKey != (int)GEnum.SystemCode.Contra))
                            {
                                svrdocGrand = (decimal)dtSvrData.Rows[0]["DocApplyAmtF"];
                                svrdocHome = (decimal)dtSvrData.Rows[0]["DocApplyAmtH"] ;
                            }
                            else
                            {
                                svrdocGrand = (decimal)dtSvrData.Rows[0]["DocGrand"];
                                svrdocHome = (decimal)dtSvrData.Rows[0]["DocHome"];
                            }

                            if (runCheckdocApplyGainAmt)
                                svrdocHome = svrdocHome + GFunc.NEDec(dtSvrData.Rows[0]["DocApplyGainAmt"], 0);
                        }
                        #endregion

                        #region Calculate dtConHis for obj data
                        if (GFunc.CompareString(GVar.UpdateType.Obj, upType) || GFunc.CompareString(GVar.UpdateType.All, upType))
                        {
                            #region Calculate FAmt and Hamt
                            FAmt = GFunc.RndC(docGrand * docSign, GVar.RndDecs.Amtpt);
                            HAmt = GFunc.RndC(docHome * docSign, GVar.RndDecs.Amtpt);
                            #endregion

                            #region Assign CR/CH/V Amt base on DocCode and FAmt/HAmt
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Quotation:
                                case (int)GEnum.SystemCode.Reserve_Order:
                                case (int)GEnum.SystemCode.Sales_Order:
                                case (int)GEnum.SystemCode.Delivery_Order:
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:                                
                                case (int)GEnum.SystemCode.Sales_Adjustment:
                                    //  CRAmt = HAmt;
                                    if (objDoc.DocTypeNm.ToLower().Contains("non-trade"))
                                    {
                                        FNT = FAmt;
                                        HNT = HAmt;
                                    }
                                    else
                                    {
                                        FCR = FAmt;
                                        HCR = HAmt;
                                    }
                                  //  CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                 //   VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;
                                case (int)GEnum.SystemCode.Payment_Received:
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    FNT = docSign* GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtF)", "LinkDocTypeNm like 'Non-Trade%'"), 0)  ; 
                                    HNT = docSign * GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtH)", "LinkDocTypeNm like 'Non-Trade%'"), 0) ;
                                    FCH = 0;
                                    HCH = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;
                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Payment_Received:
                                case (int)GEnum.SystemCode.Cash_Adjustment:
                                  //  CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                  //  CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                 //   VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;

                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Payment_Issue:
                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                    //CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                   // CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                   // VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Contra:
                                    // CRAmt = HAmt;
                                    if (objDoc.DocTypeNm.ToLower().Contains("non-trade"))
                                    {
                                        FNT = FAmt;
                                        HNT = HAmt;
                                    }
                                    else
                                    {
                                        FCR = FAmt;
                                        HCR = HAmt;
                                    }
                                  //  CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                 //   VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Cash_Contra:
                                    //CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    //CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                    //VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;
                            }
                            #endregion

                            #region Append dtConHis from variables
                            DataRow dr = dtConHis.NewRow();
                            dr["ConKey"] = docConKey;
                            dr["Period"] = docPeriod;
                            dr["DocDC"] = docCodeKey;
                            dr["DocGrpKey"] = docGrpKey;
                            dr["DocCurrKey"] = docCurrKey;
                            dr["CrAmtF"] = FCR;
                            dr["CrAmtH"] = HCR;
                            dr["ChAmtF"] = FCH;
                            dr["ChAmtH"] = HCH;
                            dr["VAmtF"] = FV;
                            dr["VAmtH"] = HV;
                            dr["NTAmtF"] = FNT;
                            dr["NTAmtH"] = HNT;
                            dtConHis.Rows.Add(dr);
                            #endregion

                            #region run additional calculation for payment document
                            if (runCalForPayment)
                            {
                                #region Loop for Discount
                                foreach (DataRow drObj in dtDocDetItm.Rows)
                                {
                                    dr = dtConHis.NewRow();
                                    dr["ConKey"] = docConKey;
                                    dr["Period"] = docPeriod;
                                    dr["DocDC"] = docCodeKey;
                                    dr["DocGrpKey"] = docGrpKey;
                                    dr["DocCurrKey"] = drObj["LinkDocCurrKey"];

                                    switch (objDoc.DocCodeKey)
                                    {
                                        case (int)GEnum.SystemCode.Payment_Received:                                            
                                            if (GFunc.NEStr(drObj["LinkDocTypeNm"], "").ToLower().Contains("non-trade"))
                                            {
                                                dr["CrAmtF"] = 0M;
                                                dr["CrAmtH"] = 0M;
                                                dr["NTAmtF"] = docSign * -GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                                dr["NTAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            }
                                            else
                                            {
                                                dr["CrAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                                dr["CrAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                                dr["NTAmtF"] = 0M;
                                                dr["NTAmtH"] = 0M;
                                            }
                                            
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["ChAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Payment_Issue:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Contra:
                                            switch ((int)drObj["LinkDocDC"])
                                            {
                                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                                case (int)GEnum.SystemCode.AP_Opening_Balance:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = 0M;
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = 0M;
                                                    dr["VAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                                    dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                                    break;

                                                default:
                                                    dr["CrAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                                    dr["CrAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = 0M;
                                                    dr["VAmtF"] = 0M;
                                                    dr["VAmtH"] = 0M;
                                                    break;
                                            }
                                            break;

                                        case (int)GEnum.SystemCode.Cash_Contra:
                                            switch ((int)drObj["LinkDocDC"])
                                            {
                                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                                case (int)GEnum.SystemCode.AP_Opening_Balance:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = 0M;
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = 0M;
                                                    dr["VAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                                    dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                                    break;

                                                default:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = 0M;
                                                    dr["ChAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                                    dr["ChAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                                    dr["VAmtF"] = 0M;
                                                    dr["VAmtH"] = 0M;
                                                    break;
                                            }
                                            break;
                                    }
                                    dtConHis.Rows.Add(dr);
                                }
                                #endregion

                                #region Loop for GainAmt
                                foreach (DataRow drObj in dtDocDetItm.Rows)
                                {
                                    dr = dtConHis.NewRow();
                                    dr["ConKey"] = docConKey;
                                    dr["Period"] = docPeriod;
                                    dr["DocDC"] = docCodeKey;
                                    dr["DocGrpKey"] = docGrpKey;
                                    dr["DocCurrKey"] = drObj["LinkDocCurrKey"];

                                    switch (objDoc.DocCodeKey)
                                    {
                                        case (int)GEnum.SystemCode.Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            if (GFunc.NEStr(drObj["LinkDocTypeNm"], "").ToLower().Contains("non-trade"))
                                            {
                                                dr["CrAmtH"] = 0M;
                                                dr["NTAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);                                                
                                            }
                                            else
                                            {
                                                dr["CrAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                                dr["NTAmtH"] = 0M;
                                            }
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Payment_Issue:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;

                                            //dr["VAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyGainAmt"], 0); //May modified it. not ready
                                            break;
                                        case (int)GEnum.SystemCode.Contra:
                                            switch ((int)drObj["LinkDocDC"])
                                            {
                                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                                case (int)GEnum.SystemCode.AP_Opening_Balance:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = 0M;
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = 0M;
                                                    dr["VAmtF"] = 0M;
                                                    dr["VAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                                    break;

                                                default:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = 0M;
                                                    dr["VAmtF"] = 0M;
                                                    dr["VAmtH"] = 0M;
                                                    break;
                                            }
                                            break;

                                        case (int)GEnum.SystemCode.Cash_Contra:
                                            switch ((int)drObj["LinkDocDC"])
                                            {
                                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                                case (int)GEnum.SystemCode.AP_Opening_Balance:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = 0M;
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = 0M;
                                                    dr["VAmtF"] = 0M;
                                                    dr["VAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                                    break;

                                                default:
                                                    dr["CrAmtF"] = 0M;
                                                    dr["CrAmtH"] = 0M;
                                                    dr["ChAmtF"] = 0M;
                                                    dr["ChAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                                    dr["VAmtF"] = 0M;
                                                    dr["VAmtH"] = 0M;
                                                    break;
                                            }
                                            break;
                                    }
                                    dtConHis.Rows.Add(dr);
                                }
                                #endregion
                            }
                            #endregion

                            dtConHis.AcceptChanges();
                        }
                        #endregion

                        #region Calculate dtConHis for Server Data
                        if (GFunc.CompareString(GVar.UpdateType.Svr, upType) || GFunc.CompareString(GVar.UpdateType.All, upType))
                        {
                            #region Calculate FAmt and Hamt
                            FAmt = GFunc.RndC(svrdocGrand * docSign * svrTransSign, GVar.RndDecs.Amtpt);
                            HAmt = GFunc.RndC(svrdocHome * docSign * svrTransSign, GVar.RndDecs.Amtpt);
                            #endregion

                            #region Assign CR/CH/V Amt base on DocCode and FAmt/HAmt

                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Quotation:
                                case (int)GEnum.SystemCode.Reserve_Order:
                                case (int)GEnum.SystemCode.Sales_Order:
                                case (int)GEnum.SystemCode.Delivery_Order:
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:                                
                                case (int)GEnum.SystemCode.Sales_Adjustment:
                                    //  CRAmt = HAmt;
                                    if (objDoc.DocTypeNm.ToLower().Contains("non-trade"))
                                    {
                                        FNT = FAmt;
                                        HNT = HAmt;
                                    }
                                    else
                                    {
                                        FCR = FAmt;
                                        HCR = HAmt;
                                    }
                                  //  CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                  //  VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;
                                case (int)GEnum.SystemCode.Payment_Received:
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    if (dtSvrData.Rows.Count > 0)
                                    {
                                        FNT = GFunc.RndC(GFunc.NEDec(dtSvrData.Rows[0]["NonTradeApplyPayAmtF"], 0) * docSign * svrTransSign, GVar.RndDecs.Amtpt);
                                        HNT = GFunc.RndC(GFunc.NEDec(dtSvrData.Rows[0]["NonTradeApplyPayAmtH"], 0) * docSign * svrTransSign, GVar.RndDecs.Amtpt);
                                    }
                                    else
                                    {
                                        FNT = 0;
                                        HNT = 0;
                                    }
                                    FCH = 0;
                                    HCH = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;
                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Payment_Received:
                                case (int)GEnum.SystemCode.Cash_Adjustment:                                    
                                    FCR = 0;
                                    HCR = 0;                                    
                                    FCH = FAmt;
                                    HCH = HAmt;                                    
                                    FV = 0;
                                    HV = 0;
                                    break;

                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Payment_Issue:
                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                    //CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                   // CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    //VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Contra:
                                    //CRAmt = HAmt;
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    //CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    //VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Cash_Contra:
                                    //CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    //CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                    //VAmt = 0;
                                    //VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;
                            }
                            #endregion

                            #region Append dtConHis from variables
                            DataRow dr = dtConHis.NewRow();

                            dr["ConKey"] = svrdocConKey;
                            dr["Period"] = svrdocPeriod;
                            dr["DocDC"] = docCodeKey;
                            dr["DocGrpKey"] = svrdocGrpKey;
                            dr["DocCurrKey"] = svrdocCurrKey;
                            dr["CrAmtF"] = FCR;
                            dr["CrAmtH"] = HCR;
                            dr["ChAmtF"] = FCH;
                            dr["ChAmtH"] = HCH;
                            dr["VAmtF"] = FV;
                            dr["VAmtH"] = HV;
                            dr["NTAmtF"] = FNT;
                            dr["NTAmtH"] = HNT;
                            dtConHis.Rows.Add(dr);
                            #endregion

                            #region run additional calculation for payment document
                            if (runCalForPayment)
                            {
                                foreach (DataRow drSvr in dtSvrConHis.Rows)
                                {
                                    dr = dtConHis.NewRow();
                                    dr["ConKey"] = svrdocConKey;
                                    dr["Period"] = svrdocPeriod;
                                    dr["DocDC"] = docCodeKey;
                                    dr["DocGrpKey"] = svrdocGrpKey;
                                    dr["DocCurrKey"] = drSvr["DocCurrKey"];

                                    switch (objDoc.DocCodeKey)
                                    {
                                        case (int)GEnum.SystemCode.Payment_Received:
                                            dr["CrAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtF"], 0);
                                            dr["CrAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtH"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            dr["NTAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["NTAmtF"], 0);
                                            dr["NTAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["NTAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtF"], 0);
                                            dr["ChAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtH"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Payment_Issue:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtF"], 0);
                                            dr["VAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Contra:
                                            dr["CrAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtF"], 0);
                                            dr["CrAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtH"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtF"], 0);
                                            dr["VAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Contra:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtF"], 0);
                                            dr["ChAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtH"], 0);
                                            dr["VAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtF"], 0);
                                            dr["VAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtH"], 0);
                                            break;
                                    }
                                    dtConHis.Rows.Add(dr);
                                }
                            }
                            #endregion

                            dtConHis.AcceptChanges();
                        }
                        #endregion

                        #region Validation for Exceed Credit Limit and Term
                        if (runCheck)
                        {
                            #region set check process to run
                            limitControlOpt = SysOptionUtility.GetInt("CheckCustomerLimit");                           
                            switch (limitControlOpt)
                            {
                                case 20:    //warn if exceed credit limit
                                    runCreditLimitCheck = true;
                                    break;

                                case 30:    //can't save if exceed credit limit
                                    runCreditLimitCheck = true;
                                    runCreditLimitControl = true;
                                    break;

                                case 40:	//warn if exceed term
                                    runExceedTermCheck = true;
                                    break;

                                case 50:	//can't save if exceed term
                                    runExceedTermCheck = true;
                                    runExceedTermControl = true;
                                    break;

                                case 60:	//warn if exceed credit limit or term
                                    runCreditLimitCheck = true;
                                    runExceedTermCheck = true;
                                    break;

                                case 70:	//can't save if exceed credit limit or term
                                    runCreditLimitCheck = true;
                                    runCreditLimitControl = true;
                                    runExceedTermCheck = true;
                                    runExceedTermControl = true;
                                    break;
                            }
                            #endregion

                            #region credit limit check   
                           
                            string DocTypeNm = "";
                            int DocTermKey = 0;
                            REFTerm objterm = null;
                            if ((SysOptionUtility.DatabaseBranchCode == DBCode.BHM || SysOptionUtility.DatabaseBranchCode == DBCode.GLH) && (objDoc.DocCodeKey == (int)GEnum.SystemCode.Reserve_Order || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order))
                            {
                                DocTypeNm = GFunc.NEStr(GFunc.GetStringPropertyValue("DocTypeNm", objDoc), "");
                                DocTermKey = GFunc.NEInt(GFunc.GetIntPropertyValue("DocTermKey", objDoc), 0);
                                objterm = REFTerm.Get(DocTermKey);
                                if (DocTypeNm.ToLower().Contains("cash") == false && (objterm.TermID != "ADVANCE PAYMENT" && objterm.TermID != "CASH" && objterm.TermID != "COD" && objterm.TermID != "CREDIT CARD PAYMENT" && objterm.TermID != "TT PAYMENT" && objterm.TermID != "L/C"))
                                {
                                    #region get link arro dockey 
                                    int LinkDocKey = 0;
                                    if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order && SysOptionUtility.DatabaseBranchCode == DBCode.BHM)
                                    {
                                        DataRow[] drs = dtDocDetItm.Select("ISNULL(ARRODK,0) >0");
                                        if (drs != null)
                                            if (drs.Length > 0)
                                            {
                                                LinkDocKey = GFunc.NEInt(drs[0]["ARRODK"], 0);
                                            }
                                    }
                                    #endregion
                                    using (SqlConnection cn = new SqlConnection(AppInfor.currentDBConnectionStr))
                                    {
                                        cn.Open();
                                        cm = cn.CreateCommand();
                                        cm.CommandType = CommandType.StoredProcedure;
                                        cm.CommandText = "Doc_CheckPrevApproval";
                                        cm.Parameters.AddWithValue("@DocKey", GFunc.NEInt(GFunc.GetIntPropertyValue("DocKey", objDoc), 0));
                                        cm.Parameters.AddWithValue("@DocCodeKey", GFunc.NEInt(GFunc.GetIntPropertyValue("DocCodeKey", objDoc), 0));
                                        cm.Parameters.AddWithValue("@LinkDocKey", LinkDocKey);
                                        cm.Parameters.AddWithValue("@IsApproved", false);
                                        cm.Parameters["@IsApproved"].Direction = ParameterDirection.Output;
                                        cm.Parameters.AddWithValue("@NewAmount", GFunc.NEDec(GFunc.GetDecimalPropertyValue("DocHome", objDoc), 0));

                                        cm.ExecuteNonQuery();

                                        if (Boolean.Parse(cm.Parameters["@IsApproved"].Value.ToString()) == true)
                                            runCreditLimitCheck = false;
                                        else
                                            runCreditLimitCheck = true;

                                        cn.Close();
                                    }
                                }
                                
                            }
                           

                             if (runCreditLimitCheck)
                             {
                                decimal transAmount = GFunc.NEDec(dtConHis.Compute("SUM(CrAmtH)", ""), 0);
                                using (SqlConnection cn = new SqlConnection(AppInfor.currentDBConnectionStr))
                                {
                                    cn.Open();
                                    cm = cn.CreateCommand();
                                    cm.CommandType = CommandType.StoredProcedure;
                                    cm.CommandText = "Doc_CheckExceedTerm";
                                    cm.Parameters.AddWithValue("@Option", (Int32)0);
                                    cm.Parameters.AddWithValue("@ConKey", docConKey);
                                    if (SysOptionUtility.DatabaseBranchCode == DBCode.BHM) 
                                        cm.Parameters.AddWithValue("@DocConNm", GFunc.NEStr(GFunc.GetStringPropertyValue("DocConNm", objDoc), ""));                                   
                                    cm.Parameters.AddWithValue("@Exceed", false);
                                    cm.Parameters["@Exceed"].Direction = ParameterDirection.Output;
                                    cm.Parameters.AddWithValue("@NewAmount", transAmount);
                                   
                                    SqlParameter pAmountExceeded = new SqlParameter("@AmountExceeded", SqlDbType.Decimal, sizeof(decimal), ParameterDirection.Output, true, (byte)20, (byte)2, "", DataRowVersion.Default, 0);
                                    cm.Parameters.Add(pAmountExceeded);
                                    cm.ExecuteNonQuery();

                                    if (Boolean.Parse(cm.Parameters["@Exceed"].Value.ToString()) == true)
                                    {
                                        exceedAmt = GFunc.NEDec(cm.Parameters["@AmountExceeded"].Value, 0);
                                    }
                                }
                                if (exceedAmt > 0)
                                {
                                    if (runCreditLimitControl)
                                    {                                       
                                        MsgBox.Show("Credit Limit has been exceeded by : " + exceedAmt);
                                        cancelProcess = true;
                                        return dtConHis;

                                    }
                                    else
                                    {
                                        if (firstTime)
                                        {
                                            //if (MsgBox.Show("Credit Limit has been exceeded by : " + exceedAmt + " , continue ?", GEnum.MsgBoxButton.Yes, GEnum.MsgBoxButton.No) == GEnum.MsgBoxButton.No)
                                            if ((SysOptionUtility.DatabaseBranchCode == DBCode.BHM || SysOptionUtility.DatabaseBranchCode == DBCode.GLH) && (objDoc.DocCodeKey == (int)GEnum.SystemCode.Reserve_Order || objDoc.DocCodeKey == (int)GEnum.SystemCode.Sales_Order)
                                            && (DocTypeNm.ToLower().Contains("cash") == false && (objterm.TermID != "ADVANCE PAYMENT" && objterm.TermID != "CASH" && objterm.TermID != "COD" && objterm.TermID != "CREDIT CARD PAYMENT" && objterm.TermID != "TT PAYMENT" && objterm.TermID != "L/C")))
                                            {                                               
                                                if (MsgBox.Show("Credit Limit has been exceeded by : " + exceedAmt + " , Are you sure you want to request approval from Management?", GEnum.MsgBoxButton.Yes, GEnum.MsgBoxButton.No) == GEnum.MsgBoxButton.No)
                                                {
                                                    userContinueCLExceeded = false;
                                                    cancelProcess = true;
                                                    return dtConHis;
                                                }
                                                else
                                                {
                                                    userContinueCLExceeded = true;
                                                }
                                                                                             
                                            }
                                            else
                                            {
                                                if (MsgBox.Show("Credit Limit has been exceeded by : " + exceedAmt + " , continue ?", GEnum.MsgBoxButton.Yes, GEnum.MsgBoxButton.No) == GEnum.MsgBoxButton.No)
                                                {
                                                    userContinueCLExceeded = false;
                                                    cancelProcess = true;
                                                    return dtConHis;
                                                }
                                                else
                                                {
                                                    userContinueCLExceeded = true;
                                                }
                                            }
                                               
                                        }
                                        else if (!userContinueCLExceeded)
                                        {
                                            MsgBox.Show("Credit Limit exceeded condition has occured while waiting for your response. Process is cancelled. Please try again.");
                                            cancelProcess = true;
                                            return dtConHis;
                                        }
                                        else //Second time and userContinueCLExceeded
                                        {
                                            Hashtable ht = new Hashtable();
                                            ht.Add(GEnum.Details.Doc_Itm, dtDocDetItm);
                                            SysAuditLogUtility.AddAuditLog(GEnum.AuditLogMode.Doc_Exceed_CreditLimit, (GEnum.SystemCode)objDoc.DocCodeKey.Value, objDoc.DocKey, objDoc.DocID, DateTime.Now, objDoc.DocTypeNm, objDoc, ht);
                                            ht = null;
                                        }
                                    }
                                }
                            }
                            #endregion

                            #region exceed term check
                            if (runExceedTermCheck)
                            {
                                bool exceeded = false;

                                using (SqlConnection cn = new SqlConnection(AppInfor.currentDBConnectionStr))
                                {
                                    cn.Open();
                                    cm = cn.CreateCommand();
                                    cm.CommandType = CommandType.StoredProcedure;
                                    cm.CommandText = "Doc_CheckExceedTerm";
                                    cm.Parameters.AddWithValue("@Option", (Int32)1);
                                    cm.Parameters.AddWithValue("@ConKey", GFunc.NEInt(GFunc.GetPropertyValue("DocConKey", objDoc), 0));                                   
                                    cm.Parameters.Add("@Exceed", SqlDbType.Decimal);
                                    cm.Parameters["@Exceed"].Direction = ParameterDirection.Output;
                                    cm.Parameters.Add("@NewAmount", SqlDbType.Decimal);
                                    cm.Parameters["@NewAmount"].Value = 0;
                                    cm.Parameters.Add("@AmountExceeded", SqlDbType.Decimal);
                                    cm.Parameters["@AmountExceeded"].Value = 0M;
                                    cm.Parameters["@AmountExceeded"].Direction = ParameterDirection.Output;
                                    cm.ExecuteNonQuery();

                                    if (int.Parse(cm.Parameters["@Exceed"].Value.ToString()) == 1)
                                    {
                                        exceeded = true;
                                    }
                                }
                                if (exceeded)
                                {
                                    if (runExceedTermControl)
                                    {
                                        MsgBox.Show("There are document that has exceeded it's term");
                                        cancelProcess = true;
                                        return dtConHis;
                                    }
                                    else
                                    {
                                        if (firstTime)
                                        {
                                            if (MsgBox.Show("There are document that has exceeded it's term , continue ?", GEnum.MsgBoxButton.Yes, GEnum.MsgBoxButton.No) == GEnum.MsgBoxButton.No)
                                            {
                                                cancelProcess = true;
                                                return dtConHis;
                                            }
                                            else
                                                userContinueTermExceeded = true;
                                        }
                                        else if (!userContinueTermExceeded)
                                        {
                                            MsgBox.Show("Term exceeded condition has occured while waiting for your response. Process is cancelled. Please try again.");
                                            cancelProcess = true;
                                            return dtConHis;
                                        }
                                        else //Second time and userContinueTermExceeded
                                        {
                                            Hashtable ht = new Hashtable();
                                            ht.Add(GEnum.Details.Doc_Itm, dtDocDetItm);
                                            SysAuditLogUtility.AddAuditLog(GEnum.AuditLogMode.Doc_Exceed_Term, (GEnum.SystemCode)objDoc.DocCodeKey.Value, objDoc.DocKey, objDoc.DocID, DateTime.Now, objDoc.DocTypeNm, objDoc, ht);
                                            ht = null;
                                        }
                                    }
                                }
                            }
                            #endregion
                        }
                        #endregion

                        return dtConHis;
                    default:
                        return new DataTable();
                }
            }
            catch (TAException tex)
            {
                throw Error(tex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
        }//Completed
        private static DataTable Doc_CV_Prepare(SqlConnection cn, Document objDoc, DataTable dtDocDetItm, DataTable dtSvrData, string upType)
        {
            try
            {
                #region Local Variables

                //Process Variables
               // int limitControlOpt = 0;
                bool runCheck = false;
               // bool runCreditLimitCheck = false;
               // bool runCreditLimitControl = false;
              //  bool runExceedTermCheck = false;
              //  bool runExceedTermControl = false;
                bool runCheckdocApplyGainAmt = false;
                bool runCalForPayment = false;
               // decimal exceedAmt = 0;
              //  SqlCommand cm = null;

                //Common Document variables
                int docCodeKey = 0;
                short docSign = 0;

                //Obj Variables
                int docConKey = 0;
                int docPeriod = 0;
                int docGrpKey = 0;
                int docCurrKey = 0;
                decimal docGrand = 0;
                decimal docHome = 0;
              //  decimal docApplyGainAmt = 0;
               // decimal docPaymentDetAmtH = 0;

                //Server Variables
                int svrTransSign = -1;
                int svrdocConKey = 0;
                int svrdocPeriod = 0;
                int svrdocGrpKey = 0;
                int svrdocCurrKey = 0;
                decimal svrdocGrand = 0;
                decimal svrdocHome = 0;
               // decimal svrdocApplyGainAmt = 0;
               // decimal svrdocPaymentDetAmtH = 0;

                //Variable for Balance Calculation
                decimal? CRAmt = 0;
                decimal? CHAmt = 0;
                decimal? VAmt = 0;
                decimal? FCR = 0;
                decimal? FCH = 0;
                decimal? FV = 0;
                decimal? HCR = 0;
                decimal? HCH = 0;
                decimal? HV = 0;
                decimal? FAmt = 0;
                decimal? HAmt = 0;

                decimal? FNT = 0;
                decimal? HNT = 0;
                DataTable dtSvrConHis = null;
                #endregion

                switch (objDoc.DocCodeKey)
                {
                    case (int)GEnum.SystemCode.Sales_Order:
                    case (int)GEnum.SystemCode.Reserve_Order:
                    case (int)GEnum.SystemCode.Delivery_Order:
                    case (int)GEnum.SystemCode.Sales_Invoice:
                    case (int)GEnum.SystemCode.Sales_Debit_Note:
                    case (int)GEnum.SystemCode.Sales_Credit_Note:
                    case (int)GEnum.SystemCode.Sales_Adjustment:
                    case (int)GEnum.SystemCode.Payment_Received:
                    case (int)GEnum.SystemCode.Contra:
                    case (int)GEnum.SystemCode.Cash_Sale:
                    case (int)GEnum.SystemCode.Cash_Debit_Note:
                    case (int)GEnum.SystemCode.Cash_Credit_Note:
                    case (int)GEnum.SystemCode.Cash_Adjustment:
                    case (int)GEnum.SystemCode.Cash_Payment_Received:
                    case (int)GEnum.SystemCode.Cash_Contra:
                    case (int)GEnum.SystemCode.Purchase_Order:
                    case (int)GEnum.SystemCode.Purchase_Invoice:
                    case (int)GEnum.SystemCode.Purchase_Debit_Note:
                    case (int)GEnum.SystemCode.Purchase_Credit_Note:
                    case (int)GEnum.SystemCode.Purchase_Adjustment:
                    case (int)GEnum.SystemCode.Payment_Issue:

                        #region Creating dtConHis table structure
                        DataTable dtConHis = new DataTable("ConHistory");
                        dtConHis.Columns.Add("ConKey", typeof(int));
                        dtConHis.Columns.Add("Period", typeof(int));
                        dtConHis.Columns.Add("DocDC", typeof(int));
                        dtConHis.Columns.Add("DocGrpKey", typeof(int));
                        dtConHis.Columns.Add("DocCurrKey", typeof(int));
                        dtConHis.Columns.Add("CRAmt", typeof(decimal));
                        dtConHis.Columns.Add("ChAmt", typeof(decimal));
                        dtConHis.Columns.Add("VAmt", typeof(decimal));
                        dtConHis.Columns.Add("CrAmtF", typeof(decimal));
                        dtConHis.Columns.Add("CrAmtH", typeof(decimal));
                        dtConHis.Columns.Add("ChAmtF", typeof(decimal));
                        dtConHis.Columns.Add("ChAmtH", typeof(decimal));
                        dtConHis.Columns.Add("VAmtF", typeof(decimal));
                        dtConHis.Columns.Add("VAmtH", typeof(decimal));
                        dtConHis.Columns.Add("NTAmtF", typeof(decimal));
                        dtConHis.Columns.Add("NTAmtH", typeof(decimal));

                        //set default to zero
                        foreach (DataColumn col in dtConHis.Columns)
                        {
                            col.DefaultValue = 0;
                        }

                        #endregion

                        #region set check condition by doccodekey
                        switch (objDoc.DocCodeKey)
                        {
                            case (int)GEnum.SystemCode.Delivery_Order:
                            case (int)GEnum.SystemCode.Sales_Invoice:
                            case (int)GEnum.SystemCode.Sales_Debit_Note:
                                runCheck = true;
                                break;

                            case (int)GEnum.SystemCode.Sales_Credit_Note:
                                runCheckdocApplyGainAmt = true;
                                runCheck = true;
                                break;

                            case (int)GEnum.SystemCode.Purchase_Credit_Note:
                            case (int)GEnum.SystemCode.Cash_Credit_Note:
                                runCheckdocApplyGainAmt = true;
                                break;

                            case (int)GEnum.SystemCode.Cash_Sale:
                            case (int)GEnum.SystemCode.Cash_Debit_Note:
                            case (int)GEnum.SystemCode.Purchase_Invoice:
                            case (int)GEnum.SystemCode.Purchase_Debit_Note:
                            case (int)GEnum.SystemCode.Sales_Adjustment:
                            case (int)GEnum.SystemCode.Cash_Adjustment:
                            case (int)GEnum.SystemCode.Purchase_Adjustment:
                                break;

                            case (int)GEnum.SystemCode.Payment_Received:
                            case (int)GEnum.SystemCode.Cash_Payment_Received:
                            case (int)GEnum.SystemCode.Payment_Issue:
                            case (int)GEnum.SystemCode.Cash_Contra:
                            case (int)GEnum.SystemCode.Contra:

                                runCalForPayment = true;

                                //get server payment detail DiscountH and GainLossAmtH
                                List<SqlParameter> parmList = new List<SqlParameter>();
                                parmList.Add(new SqlParameter("@DocCodeKey", objDoc.DocCodeKey));
                                parmList.Add(new SqlParameter("@DocKey", objDoc.DocKey));
                                dtSvrConHis = GFunc.ExecuteProc(cn, "Doc_PrepareConHis_Get", parmList);
                                break;

                            default:
                                return dtConHis;
                        }
                        #endregion

                        #region Get obj and server data
                        docCodeKey = (int)objDoc.DocCodeKey;
                        docSign = (short)objDoc.DocSign.Value;

                        //Obj Calculation
                        docConKey = GFunc.NEInt((int)GFunc.GetIntPropertyValue("DocConKey", objDoc), 0);
                        docPeriod = Convert.ToInt32(GFunc.NEDateTime(objDoc.DocDate, DateTime.Today).ToString("yyyyMM"));
                        docGrpKey = (int)GFunc.GetIntPropertyValue("DocGrpKey", objDoc);
                        docCurrKey = (int)GFunc.GetIntPropertyValue("DocCurrKey", objDoc);

                        if (runCalForPayment && (objDoc.DocCodeKey != (int)GEnum.SystemCode.Cash_Contra && objDoc.DocCodeKey != (int)GEnum.SystemCode.Contra))
                        {
                            //docGrand = (decimal)GFunc.GetDecimalPropertyValue("DocApplyAmtF", objDoc);
                            //docHome = (decimal)GFunc.GetDecimalPropertyValue("DocApplyAmtH", objDoc) + docPaymentDetAmtH;
                            docGrand = GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtF)", "LinkDocTypeNm not like 'Non-Trade%'"), 0);
                            docHome = GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtH)", "LinkDocTypeNm not like 'Non-Trade%'"), 0);
                        }
                        else
                        {
                            docGrand = (decimal)GFunc.GetDecimalPropertyValue("DocGrand", objDoc);
                            docHome = (decimal)GFunc.GetDecimalPropertyValue("DocHome", objDoc);
                        }

                        if (runCheckdocApplyGainAmt)
                            docHome = docHome + GFunc.NEDec((decimal)GFunc.GetDecimalPropertyValue("DocApplyGainAmt", objDoc), 0);

                        //Server Calculaton
                        if (dtSvrData != null)  //when this routine is call from multisaveprocess, this dtSvrData will be null
                        {
                            if (dtSvrData.Rows.Count > 0)
                            {
                                svrdocConKey = (int)dtSvrData.Rows[0]["DocConKey"];
                                svrdocPeriod = Convert.ToInt32(GFunc.NEDateTime(dtSvrData.Rows[0]["DocDate"], DateTime.Today).ToString("yyyyMM"));
                                svrdocGrpKey = (int)dtSvrData.Rows[0]["DocGrpKey"];
                                svrdocCurrKey = (int)dtSvrData.Rows[0]["DocCurrKey"];

                                if (runCalForPayment && (objDoc.DocCodeKey != (int)GEnum.SystemCode.Cash_Contra && objDoc.DocCodeKey != (int)GEnum.SystemCode.Contra))
                                {
                                    svrdocGrand = (decimal)dtSvrData.Rows[0]["DocApplyAmtF"];
                                    svrdocHome = (decimal)dtSvrData.Rows[0]["DocApplyAmtH"];// + svrdocPaymentDetAmtH;
                                }
                                else
                                {
                                    svrdocGrand = (decimal)dtSvrData.Rows[0]["DocGrand"];
                                    svrdocHome = (decimal)dtSvrData.Rows[0]["DocHome"];
                                }

                                if (runCheckdocApplyGainAmt)
                                    svrdocHome = svrdocHome + GFunc.NEDec(dtSvrData.Rows[0]["DocApplyGainAmt"], 0);
                            }
                        }
                        #endregion

                        #region Calculate dtConHis for obj data
                        if (GFunc.CompareString(GVar.UpdateType.Obj, upType) || GFunc.CompareString(GVar.UpdateType.All, upType))
                        {
                            #region Calculate FAmt and Hamt
                            FAmt = GFunc.RndC(docGrand * docSign, GVar.RndDecs.Amtpt);
                            HAmt = GFunc.RndC(docHome * docSign, GVar.RndDecs.Amtpt);
                            #endregion

                            #region Assign CR/CH/V Amt base on DocCode and FAmt/HAmt
                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:                                
                                case (int)GEnum.SystemCode.Sales_Adjustment:
                                    CRAmt = HAmt;
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    CHAmt = 0;
                                    if (objDoc.DocTypeNm.ToLower().Contains("non-trade"))
                                    {
                                        FNT = FAmt;
                                        HNT = HAmt;
                                    }
                                    else
                                    {
                                        FCR = FAmt;
                                        HCR = HAmt;
                                    }
                                    FCH = 0;
                                    HCH = 0;
                                    VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    
                                    break;
                                case (int)GEnum.SystemCode.Payment_Received:
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    FNT = docSign * GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtF)", "LinkDocTypeNm like 'Non-Trade%'"), 0);
                                    HNT = docSign * GFunc.NEDec(dtDocDetItm.Compute("Sum(ItmApplyPayAmtH)", "LinkDocTypeNm like 'Non-Trade%'"), 0);
                                    FCH = 0;
                                    HCH = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;

                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Payment_Received:
                                case (int)GEnum.SystemCode.Cash_Adjustment:
                                    CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                    VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;

                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Payment_Issue:
                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                    CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Contra:
                                    CRAmt = HAmt;
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    if (objDoc.DocTypeNm.ToLower().Contains("non-trade"))
                                    {
                                        FNT = FAmt;
                                        HNT = HAmt;
                                    }
                                    else
                                    {
                                        FCR = FAmt;
                                        HCR = HAmt;
                                    }
                                    CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Cash_Contra:
                                    CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                    VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;
                            }
                            #endregion

                            #region Append dtConHis from variables
                            DataRow dr = dtConHis.NewRow();
                            dr["ConKey"] = docConKey;
                            dr["Period"] = docPeriod;
                            dr["DocDC"] = docCodeKey;
                            dr["DocGrpKey"] = docGrpKey;
                            dr["DocCurrKey"] = docCurrKey;
                            dr["CrAmtF"] = FCR;
                            dr["CrAmtH"] = HCR;
                            dr["ChAmtF"] = FCH;
                            dr["ChAmtH"] = HCH;
                            dr["VAmtF"] = FV;
                            dr["VAmtH"] = HV;
                            dr["NTAmtF"] = FNT;
                            dr["NTAmtH"] = HNT;
                            dtConHis.Rows.Add(dr);
                            #endregion

                            #region run additional calculation for payment document
                            if (runCalForPayment)
                            {
                                #region Loop for Discount
                                foreach (DataRow drObj in dtDocDetItm.Rows)
                                {
                                    dr = dtConHis.NewRow();
                                    dr["ConKey"] = docConKey;
                                    dr["Period"] = docPeriod;
                                    dr["DocDC"] = docCodeKey;
                                    dr["DocGrpKey"] = docGrpKey;
                                    dr["DocCurrKey"] = drObj["LinkDocCurrKey"];

                                    switch (objDoc.DocCodeKey)
                                    {
                                        case (int)GEnum.SystemCode.Payment_Received:
                                            dr["CrAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["CrAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["ChAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Payment_Issue:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Contra:
                                            dr["CrAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["CrAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Contra:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["ChAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            dr["VAmtF"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtF"], 0);
                                            dr["VAmtH"] = docSign * GFunc.NEDec(drObj["ItmApplyDisAmtH"], 0);
                                            break;
                                    }
                                    dtConHis.Rows.Add(dr);
                                }
                                #endregion

                                #region Loop for GainAmt
                                foreach (DataRow drObj in dtDocDetItm.Rows)
                                {
                                    dr = dtConHis.NewRow();
                                    dr["ConKey"] = docConKey;
                                    dr["Period"] = docPeriod;
                                    dr["DocDC"] = docCodeKey;
                                    dr["DocGrpKey"] = docGrpKey;
                                    dr["DocCurrKey"] = drObj["LinkDocCurrKey"];

                                    switch (objDoc.DocCodeKey)
                                    {
                                        case (int)GEnum.SystemCode.Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Payment_Issue:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Contra:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Contra:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = docSign * -GFunc.NEDec(drObj["ItmApplyGainAmt"], 0);
                                            break;
                                    }
                                    dtConHis.Rows.Add(dr);
                                }
                                #endregion
                            }
                            #endregion

                            dtConHis.AcceptChanges();
                        }
                        #endregion

                        #region Calculate dtConHis for Server Data
                        if (GFunc.CompareString(GVar.UpdateType.Svr, upType) || GFunc.CompareString(GVar.UpdateType.All, upType))
                        {
                            #region Calculate FAmt and Hamt
                            FAmt = GFunc.RndC(svrdocGrand * docSign * svrTransSign, GVar.RndDecs.Amtpt);
                            HAmt = GFunc.RndC(svrdocHome * docSign * svrTransSign, GVar.RndDecs.Amtpt);
                            #endregion

                            #region Assign CR/CH/V Amt base on DocCode and FAmt/HAmt

                            switch (objDoc.DocCodeKey)
                            {
                                case (int)GEnum.SystemCode.Sales_Invoice:
                                case (int)GEnum.SystemCode.Sales_Credit_Note:
                                case (int)GEnum.SystemCode.Sales_Debit_Note:
                                case (int)GEnum.SystemCode.Payment_Received:
                                case (int)GEnum.SystemCode.Sales_Adjustment:
                                    CRAmt = HAmt;
                                    FCR = 0;
                                    HCR = 0;
                                    if (objDoc.DocTypeNm.ToLower().Contains("non-trade"))
                                    {
                                        FNT = FAmt;
                                        HNT = HAmt;
                                    }
                                    else
                                    {
                                        FCR = FAmt;
                                        HCR = HAmt;
                                    }
                                    CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;

                                case (int)GEnum.SystemCode.Cash_Sale:
                                case (int)GEnum.SystemCode.Cash_Credit_Note:
                                case (int)GEnum.SystemCode.Cash_Debit_Note:
                                case (int)GEnum.SystemCode.Cash_Payment_Received:
                                case (int)GEnum.SystemCode.Cash_Adjustment:
                                    CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                    VAmt = 0;
                                    FV = 0;
                                    HV = 0;
                                    break;

                                case (int)GEnum.SystemCode.Purchase_Invoice:
                                case (int)GEnum.SystemCode.Purchase_Credit_Note:
                                case (int)GEnum.SystemCode.Purchase_Debit_Note:
                                case (int)GEnum.SystemCode.Payment_Issue:
                                case (int)GEnum.SystemCode.Purchase_Adjustment:
                                    CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Contra:
                                    CRAmt = HAmt;
                                    FCR = FAmt;
                                    HCR = HAmt;
                                    CHAmt = 0;
                                    FCH = 0;
                                    HCH = 0;
                                    VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;

                                case (int)GEnum.SystemCode.Cash_Contra:
                                    CRAmt = 0;
                                    FCR = 0;
                                    HCR = 0;
                                    CHAmt = HAmt;
                                    FCH = FAmt;
                                    HCH = HAmt;
                                    VAmt = 0;
                                    VAmt = HAmt;
                                    FV = FAmt;
                                    HV = HAmt;
                                    break;
                            }
                            #endregion

                            #region Append dtConHis from variables
                            DataRow dr = dtConHis.NewRow();

                            dr["ConKey"] = svrdocConKey;
                            dr["Period"] = svrdocPeriod;
                            dr["DocDC"] = docCodeKey;
                            dr["DocGrpKey"] = svrdocGrpKey;
                            dr["DocCurrKey"] = svrdocCurrKey;
                            dr["CrAmtF"] = FCR;
                            dr["CrAmtH"] = HCR;
                            dr["ChAmtF"] = FCH;
                            dr["ChAmtH"] = HCH;
                            dr["VAmtF"] = FV;
                            dr["VAmtH"] = HV;
                            dr["NTAmtF"] = FV;
                            dr["NTAmtH"] = HV;
                            dtConHis.Rows.Add(dr);
                            #endregion

                            #region run additional calculation for payment document
                            if (runCalForPayment)
                            {
                                foreach (DataRow drSvr in dtSvrConHis.Rows)
                                {
                                    dr = dtConHis.NewRow();
                                    dr["ConKey"] = svrdocConKey;
                                    dr["Period"] = svrdocPeriod;
                                    dr["DocDC"] = docCodeKey;
                                    dr["DocGrpKey"] = svrdocGrpKey;
                                    dr["DocCurrKey"] = drSvr["DocCurrKey"];

                                    switch (objDoc.DocCodeKey)
                                    {
                                        case (int)GEnum.SystemCode.Payment_Received:
                                            dr["CrAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtF"], 0);
                                            dr["CrAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtH"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtF"], 0);
                                            dr["ChAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtH"], 0);
                                            dr["VAmtF"] = 0M;
                                            dr["VAmtH"] = 0M;
                                            break;
                                        case (int)GEnum.SystemCode.Payment_Issue:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtF"], 0);
                                            dr["VAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Contra:
                                            dr["CrAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtF"], 0);
                                            dr["CrAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["CrAmtH"], 0);
                                            dr["ChAmtF"] = 0M;
                                            dr["ChAmtH"] = 0M;
                                            dr["VAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtF"], 0);
                                            dr["VAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtH"], 0);
                                            break;
                                        case (int)GEnum.SystemCode.Cash_Contra:
                                            dr["CrAmtF"] = 0M;
                                            dr["CrAmtH"] = 0M;
                                            dr["ChAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtF"], 0);
                                            dr["ChAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["ChAmtH"], 0);
                                            dr["VAmtF"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtF"], 0);
                                            dr["VAmtH"] = docSign * svrTransSign * GFunc.NEDec(drSvr["VAmtH"], 0);
                                            break;
                                    }
                                    dtConHis.Rows.Add(dr);
                                }
                            }
                            #endregion

                            dtConHis.AcceptChanges();
                        }
                        #endregion

                        return dtConHis;

                    default:
                        return new DataTable();
                }
            }
            catch (TAException tex)
            {
                throw Error(tex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
        }//Completed
        private static DataTable Doc_Posting_Prepare(Document objDoc, int ButtonAction, Hashtable dtDetails, string DocAutoID)
        {
            //Currently DocAutoID is not used as the ObjDoc.DocID has been set during DocID autogenerate
            DataTable dtItem = null;
            DataTable dtExp = null;
            DataTable dtPosting = null;

            try
            {
                #region check Detail DataTable
                switch (objDoc.DocCodeKey)
                {
                    case (int)GEnum.SystemCode.Quotation:
                    case (int)GEnum.SystemCode.Purchase_Plan:
                    case (int)GEnum.SystemCode.Purchase_Request:
                    case (int)GEnum.SystemCode.Sales_Order:
                    case (int)GEnum.SystemCode.Reserve_Order:
                    case (int)GEnum.SystemCode.Purchase_Order:
                    case (int)GEnum.SystemCode.Order_Consignment:
                    case (int)GEnum.SystemCode.Sales_Order_Adjustment:
                    case (int)GEnum.SystemCode.Purchase_Order_Adjustment:
                    case (int)GEnum.SystemCode.Consignment_Order_Adjustment:
                    case (int)GEnum.SystemCode.Delivery_Order:
                    case (int)GEnum.SystemCode.Purchase_Shipment:
                    case (int)GEnum.SystemCode.Purchase_Delivery:
                    case (int)GEnum.SystemCode.Received_Consignment:
                    case (int)GEnum.SystemCode.Packing_List:
                    case (int)GEnum.SystemCode.Consignment_Settlement:
                    case (int)GEnum.SystemCode.Sales_Invoice:
                    case (int)GEnum.SystemCode.Sales_Debit_Note:
                    case (int)GEnum.SystemCode.Sales_Credit_Note:
                    case (int)GEnum.SystemCode.Cash_Sale:
                    case (int)GEnum.SystemCode.Cash_Debit_Note:
                    case (int)GEnum.SystemCode.Cash_Credit_Note:
                    case (int)GEnum.SystemCode.Purchase_Invoice:
                    case (int)GEnum.SystemCode.Purchase_Debit_Note:
                    case (int)GEnum.SystemCode.Purchase_Credit_Note:
                    case (int)GEnum.SystemCode.Contra:
                    case (int)GEnum.SystemCode.Cash_Contra:
                    case (int)GEnum.SystemCode.Inventory_Adjustment:
                    case (int)GEnum.SystemCode.Inventory_Production:
                    case (int)GEnum.SystemCode.Inventory_Transfer:
                    case (int)GEnum.SystemCode.Journal:
                    case (int)GEnum.SystemCode.Deposit:
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Itm, dtDetails, ref dtItem);
                        break;
                    case (int)GEnum.SystemCode.Issue_Consignment:
                    case (int)GEnum.SystemCode.Return_Consignment:
                    case (int)GEnum.SystemCode.Payment_Received:
                    case (int)GEnum.SystemCode.Cash_Payment_Received:
                    case (int)GEnum.SystemCode.Payment_Issue:
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Itm, dtDetails, ref dtItem);
                        DocComUtility.DocDetail_Get(GEnum.Details.Doc_Exp, dtDetails, ref dtExp);
                        break;
                }
                #endregion

                if (ButtonAction != (int)GEnum.DocAction.Delete)//New or Edit
                {
                    switch (objDoc.DocCodeKey)
                    {
                        case (int)GEnum.SystemCode.Sales_Invoice:
                        case (int)GEnum.SystemCode.Sales_Credit_Note:
                        case (int)GEnum.SystemCode.Sales_Debit_Note:
                        case (int)GEnum.SystemCode.Cash_Sale:
                        case (int)GEnum.SystemCode.Cash_Credit_Note:
                        case (int)GEnum.SystemCode.Cash_Debit_Note:
                            dtPosting = DTPostARIV(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Payment_Received:
                        case (int)GEnum.SystemCode.Cash_Payment_Received:
                            dtPosting = DTPostARPY(null, objDoc, dtItem, dtExp);
                            break;
                        case (int)GEnum.SystemCode.Sales_Adjustment:
                        case (int)GEnum.SystemCode.Cash_Adjustment:
                            dtPosting = DTPostARRF(null, objDoc);
                            break;
                        case (int)GEnum.SystemCode.Purchase_Invoice:
                        case (int)GEnum.SystemCode.Purchase_Credit_Note:
                        case (int)GEnum.SystemCode.Purchase_Debit_Note:
                            dtPosting = DTPostAPBL(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Payment_Issue:
                            dtPosting = DTPostAPPY(null, objDoc, dtItem, dtExp);
                            break;
                        case (int)GEnum.SystemCode.Purchase_Adjustment:
                            dtPosting = DTPostAPRF(null, objDoc);
                            break;                        
                        case (int)GEnum.SystemCode.Purchase_Delivery:
                            dtPosting = DTPostAPPD(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Contra:
                        case (int)GEnum.SystemCode.Cash_Contra:
                            dtPosting = DTPostARCT(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Inventory_Adjustment:
                            dtPosting = DTPostINADJ(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Journal:
                            dtPosting = DTPostGLJN(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Deposit:
                            dtPosting = DTPostGLDP(null, objDoc, dtItem);
                            break;
                        case (int)GEnum.SystemCode.Bank_Revaluation:
                            dtPosting = DTPostGLRV(null, objDoc, dtItem);
                            break;
                    }
                }
                return dtPosting;
            }
            catch (TAException tex)
            {
                throw Error(tex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
            finally
            {
                dtExp = null;
                dtItem = null;
            }
        }//Completed
