            dtPost.Columns.Add("DocGrpKey", typeof(int));
            dtPost.Columns.Add("DocType", typeof(int));
            dtPost.Columns.Add("DocTypeNm", typeof(string));
            dtPost.Columns.Add("DocCurrkey", typeof(int));
            dtPost.Columns.Add("DocCurrRate", typeof(decimal));
            dtPost.Columns.Add("DocCVKey", typeof(int));
            dtPost.Columns.Add("DocCVNmDoc", typeof(string));
            dtPost.Columns.Add("DocChqNum", typeof(string));
            dtPost.Columns.Add("DocRef", typeof(string));
            dtPost.Columns.Add("DocDes", typeof(string));
            dtPost.Columns.Add("DetItmSN", typeof(decimal));
            dtPost.Columns.Add("DetItmDetSN", typeof(decimal));
            dtPost.Columns.Add("DetItmKey", typeof(int));
            dtPost.Columns.Add("DetItmKeySelect", typeof(int));
            dtPost.Columns.Add("DetItmDes", typeof(string));
            dtPost.Columns.Add("DetRef", typeof(string));
            dtPost.Columns.Add("DetJobKey", typeof(int));
            dtPost.Columns.Add("DetJobPhaseKey", typeof(int));
            dtPost.Columns.Add("DetJobTaskKey", typeof(int));
            dtPost.Columns.Add("DetJobCostTypeKey", typeof(int));
            dtPost.Columns.Add("LogFC", typeof(decimal));
            dtPost.Columns.Add("LogFD", typeof(decimal));
            dtPost.Columns.Add("LogHC", typeof(decimal));
            dtPost.Columns.Add("LogHD", typeof(decimal));
            dtPost.Columns.Add("LogRecon", typeof(bool));
            dtPost.Columns.Add("LogReconPeriod", typeof(int));
            #endregion

            decimal? DocPeriod = Convert.ToInt32(GFunc.NEDateTime(objDoc.DocDate, DateTime.Today).ToString("yyyyMM"));
            int? DocBranchKey = GFunc.GetIntPropertyValue("BranchKey", objDoc);
            int? DocDeptKey = GFunc.GetIntPropertyValue("DocDeptKey", objDoc);
            int? DocTranGrpKey = GFunc.GetIntPropertyValue("DocTranGrpKey", objDoc);
            int? DocGrpKey = GFunc.GetIntPropertyValue("DocGrpKey", objDoc);
            int? DocCurrkey = GFunc.GetIntPropertyValue("DocCurrKey", objDoc);
            decimal? DocCurrRate = GFunc.GetDecimalPropertyValue("DocCurrRate", objDoc);
            int? DocCVKey = GFunc.GetIntPropertyValue("DocConKey", objDoc);
            string DocCVNmDoc = GFunc.GetStringPropertyValue("DocConNm", objDoc);
            string DocRef = GFunc.GetStringPropertyValue("DocRef", objDoc);
            string DocDes = GFunc.GetStringPropertyValue("DocDes", objDoc);

            int? DocOverallDisAcc = GFunc.GetIntPropertyValue("DocOverallDisAcc", objDoc);
            decimal? DocOverallDisAmt = GFunc.GetDecimalPropertyValue("DocOverallDisAmt", objDoc);
            int? DocTaxGrpKey = GFunc.GetIntPropertyValue("DocTaxGrpKey", objDoc);
            decimal? DocTaxTotal = GFunc.GetDecimalPropertyValue("DocTaxTotal", objDoc);
            decimal DocTaxTotalLocal = (decimal)GFunc.GetDecimalPropertyValue("DocTaxTotalLocal", objDoc);
            decimal? DocTaxGrpRate = GFunc.GetDecimalPropertyValue("DocTaxGrpRate", objDoc);
            int? DocPaidAccKey = GFunc.GetIntPropertyValue("DocPaidAccKey", objDoc);
            decimal? DocPaidAmtF = GFunc.GetDecimalPropertyValue("DocPaidAmtF", objDoc);
            decimal? DocGrand = GFunc.GetDecimalPropertyValue("DocGrand", objDoc);
            decimal? DocHome = GFunc.GetDecimalPropertyValue("DocHome", objDoc);
            decimal? DocApplyGainAmt = GFunc.GetDecimalPropertyValue("DocApplyGainAmt", objDoc);

            int? AccGSTCustom;
            int? DocAccKey = GFunc.GetIntPropertyValue("DocAccKey", objDoc);
            int? DocAddCostAccKey = GFunc.GetIntPropertyValue("DocAddCostAccKey", objDoc);
            int? DocApplyGainAccKey = GFunc.GetIntPropertyValue("DocApplyGainAccKey", objDoc);
            #endregion

            try
            {
                string docID = objDoc.DocID;

                if (cn == null)
                    AccGSTCustom = SysOptionUtility.GetInt("AccGSTCustom");
                else
                    AccGSTCustom = SysOptionUtility.GetInt("AccGSTCustom", cn);

                #region Post Tax
                if (!GFunc.IsNE(DocTaxGrpKey))
                {
                    List<SqlParameter> parmList = new List<SqlParameter>();
                    parmList.Add(new SqlParameter("@TaxGrpKey", DocTaxGrpKey));

                    if (cn == null)
                        dtIsCustomGST = GFunc.ExecuteProc("Doc_IsCustomGST", parmList);
                    else
                        dtIsCustomGST = GFunc.ExecuteProc(cn, "Doc_IsCustomGST", parmList);

                    if (dtIsCustomGST.Rows.Count != 0)
                    {
                        List<SqlParameter> TaxparmList = new List<SqlParameter>();
                        TaxparmList.Add(new SqlParameter("@DocDate", objDoc.DocDate));
                        TaxparmList.Add(new SqlParameter("@TaxGrpKey", DocTaxGrpKey));

                        if (cn == null)
                            dtTaxGrpList = GFunc.ExecuteProc("Doc_GetTaxGrpList", TaxparmList);
                        else
                            dtTaxGrpList = GFunc.ExecuteProc(cn, "Doc_GetTaxGrpList", TaxparmList);

                        if (GFunc.NEBool(dtIsCustomGST.Rows[0]["GSTCustom"], false))//GSTCustom is true
                        {
                            #region Post Custom Import Tax - Debit GST Controller and Credit Custom Import Tax Account
                            if (DocTaxTotal != 0)
                            {
                                if (dtTaxGrpList.Rows.Count != 0)
                                {
                                    decimal TaxTotalPostAmtH = 0M;
                                    if ((int)SysOptionUtility.CountryCurrency == 1)
                                        TaxTotalPostAmtH = DocTaxTotalLocal;
                                    else
                                        TaxTotalPostAmtH = GFunc.RndC(DocCurrRate * DocTaxTotal, GVar.RndDecs.Curpt);//we use 8 dec place for accuracy purpose

                                    foreach (DataRow drTax in dtTaxGrpList.Rows)
                                    {
                                        dr = dtPost.NewRow();
                                        dr["LogDC"] = objDoc.DocCodeKey;
                                        dr["LogDK"] = objDoc.DocKey;
                                        dr["LogDItm"] = 0;
                                        dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                                        dr["LogAccKey"] = (int)drTax["AccKey"];
                                        dr["LogTrans"] = PostType.TX;
                                        dr["LogTransCode"] = PostTypeCode.TX;
                                        dr["LogTaxKey"] = (int)drTax["TaxKey"];
                                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                                        dr["DocID"] = docID;
                                        dr["DocDate"] = objDoc.DocDate;
                                        dr["DocPeriod"] = DocPeriod;
                                        dr["DocBranchKey"] = DocBranchKey;
                                        dr["DocDeptKey"] = DocDeptKey;
                                        dr["DocTranGrpKey"] = DocTranGrpKey;
                                        dr["DocGrpKey"] = DocGrpKey;
                                        dr["DocType"] = objDoc.DocType;
                                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                                        dr["DocCurrkey"] = DocCurrkey;
                                        dr["DocCurrRate"] = DocCurrRate;
                                        dr["DocCVKey"] = DocCVKey;
                                        dr["DocCVNmDoc"] = DocCVNmDoc;
                                        dr["DocChqNum"] = string.Empty;
                                        dr["DocRef"] = DocRef;
                                        dr["DocDes"] = DocDes;
                                        dr["DetItmSN"] = 0M;
                                        dr["DetItmDetSN"] = 0M;
                                        dr["DetItmKey"] = 0;
                                        dr["DetItmKeySelect"] = 0;
                                        dr["DetItmDes"] = string.Empty;
                                        dr["DetRef"] = drTax["TaxDes"];
                                        dr["DetJobKey"] = 0;
                                        dr["DetJobPhaseKey"] = 0;
                                        dr["DetJobTaskKey"] = 0;
                                        dr["DetJobCostTypeKey"] = 0;
                                        dr["LogFC"] = DocComUtility.PTTax(DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "C");//Ask Mic
                                        dr["LogFD"] = DocComUtility.PTTax(DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "D");//Ask Mic
                                        dr["LogHC"] = DocComUtility.PTTax(TaxTotalPostAmtH, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "C");//Ask Mic
                                        dr["LogHD"] = DocComUtility.PTTax(TaxTotalPostAmtH, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "D");//Ask Mic
                                        dr["LogRecon"] = false;
                                        dr["LogReconPeriod"] = 0;
                                        dtPost.Rows.Add(dr);

                                        dr = dtPost.NewRow();
                                        dr["LogDC"] = objDoc.DocCodeKey;
                                        dr["LogDK"] = objDoc.DocKey;
                                        dr["LogDItm"] = 0;
                                        dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                                        dr["LogAccKey"] = AccGSTCustom;
                                        dr["LogTrans"] = PostType.TXC;
                                        dr["LogTransCode"] = PostTypeCode.TXC;
                                        dr["LogTaxKey"] = drTax["TaxKey"];
                                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                                        dr["DocID"] = docID;
                                        dr["DocDate"] = objDoc.DocDate;
                                        dr["DocPeriod"] = DocPeriod;
                                        dr["DocBranchKey"] = DocBranchKey;
                                        dr["DocDeptKey"] = DocDeptKey;
                                        dr["DocTranGrpKey"] = DocTranGrpKey;
                                        dr["DocGrpKey"] = DocGrpKey;
                                        dr["DocType"] = objDoc.DocType;
                                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                                        dr["DocCurrkey"] = DocCurrkey;
                                        dr["DocCurrRate"] = DocCurrRate;
                                        dr["DocCVKey"] = DocCVKey;
                                        dr["DocCVNmDoc"] = DocCVNmDoc;
                                        dr["DocChqNum"] = string.Empty;
                                        dr["DocRef"] = DocRef;
                                        dr["DocDes"] = DocDes;
                                        dr["DetItmSN"] = 0M;
                                        dr["DetItmDetSN"] = 0M;
                                        dr["DetItmKey"] = 0;
                                        dr["DetItmKeySelect"] = 0;
                                        dr["DetItmDes"] = string.Empty;
                                        dr["DetRef"] = drTax["TaxDes"];
                                        dr["DetJobKey"] = 0;
                                        dr["DetJobPhaseKey"] = 0;
                                        dr["DetJobTaskKey"] = 0;
                                        dr["DetJobCostTypeKey"] = 0;
                                        dr["LogFC"] = DocComUtility.PTTax(DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "C", "C");//Ask Mic
                                        dr["LogFD"] = DocComUtility.PTTax(DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "C", "D");//Ask Mic
                                        dr["LogHC"] = DocComUtility.PTTax(TaxTotalPostAmtH, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "C", "C");//Ask Mic
                                        dr["LogHD"] = DocComUtility.PTTax(TaxTotalPostAmtH, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "C", "D");//Ask Mic
                                        dr["LogRecon"] = false;
                                        dr["LogReconPeriod"] = 0;
                                        dtPost.Rows.Add(dr);

                                    }
                                }
                            }
                            #endregion
                        }
                        else
                        {
                            #region Post Tax
                            if (DocTaxTotal != 0)
                            {
                                if (dtTaxGrpList.Rows.Count != 0)
                                {
                                    foreach (DataRow drTax in dtTaxGrpList.Rows)
                                    {
                                        dr = dtPost.NewRow();
                                        dr["LogDC"] = objDoc.DocCodeKey;
                                        dr["LogDK"] = objDoc.DocKey;
                                        dr["LogDItm"] = 0;
                                        dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                                        dr["LogAccKey"] = drTax["AccKey"];
                                        dr["LogTrans"] = PostType.TX;
                                        dr["LogTransCode"] = PostTypeCode.TX;
                                        dr["LogTaxKey"] = drTax["TaxKey"];
                                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                                        dr["DocID"] = docID;
                                        dr["DocDate"] = objDoc.DocDate;
                                        dr["DocPeriod"] = DocPeriod;
                                        dr["DocBranchKey"] = DocBranchKey;
                                        dr["DocDeptKey"] = DocDeptKey;
                                        dr["DocTranGrpKey"] = DocTranGrpKey;
                                        dr["DocGrpKey"] = DocGrpKey;
                                        dr["DocType"] = objDoc.DocType;
                                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                                        dr["DocCurrkey"] = DocCurrkey;
                                        dr["DocCurrRate"] = DocCurrRate;
                                        dr["DocCVKey"] = DocCVKey;
                                        dr["DocCVNmDoc"] = DocCVNmDoc;
                                        dr["DocChqNum"] = string.Empty;
                                        dr["DocRef"] = DocRef;
                                        dr["DocDes"] = DocDes;
                                        dr["DetItmSN"] = 0M;
                                        dr["DetItmDetSN"] = 0M;
                                        dr["DetItmKey"] = 0;
                                        dr["DetItmKeySelect"] = 0;
                                        dr["DetItmDes"] = string.Empty;
                                        dr["DetRef"] = drTax["TaxDes"];
                                        dr["DetJobKey"] = 0;
                                        dr["DetJobPhaseKey"] = 0;
                                        dr["DetJobTaskKey"] = 0;
                                        dr["DetJobCostTypeKey"] = 0;
                                        dr["LogFC"] = DocComUtility.PTTax(DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "C");
                                        dr["LogFD"] = DocComUtility.PTTax(DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "D");
                                        dr["LogHC"] = DocComUtility.PTTax(DocCurrRate * DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "C");
                                        dr["LogHD"] = DocComUtility.PTTax(DocCurrRate * DocTaxTotal, GFunc.NEDec(dtTaxGrpList.Rows[0]["TaxRate"], 0) * objDoc.DocSign, DocTaxGrpRate, "D", "D");
                                        dr["LogRecon"] = false;
                                        dr["LogReconPeriod"] = 0;
                                        dtPost.Rows.Add(dr);
                                    }
                                }
                            }
                            #endregion
                        }
                    }
                }
                #endregion

                #region Post Overall Discount
                if (GFunc.IsNEZ(DocOverallDisAmt) == false)
                {
                    if (GFunc.IsNEZ(DocOverallDisAcc))
                        throw new TAException("Overall discount account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = 0;
                    dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                    dr["LogAccKey"] = DocOverallDisAcc;
                    dr["LogTrans"] = PostType.DIS;
                    dr["LogTransCode"] = PostTypeCode.DIS;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = DocDeptKey;
                    dr["DocTranGrpKey"] = DocTranGrpKey;
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = string.Empty;
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = 0M;
                    dr["DetItmDetSN"] = 0M;
                    dr["DetItmKey"] = 0;
                    dr["DetItmKeySelect"] = 0;
                    dr["DetItmDes"] = string.Empty;
                    dr["DetRef"] = GFunc.GetStringPropertyValue("DocPONum", objDoc);
                    dr["DetJobKey"] = 0;
                    dr["DetJobPhaseKey"] = 0;
                    dr["DetJobTaskKey"] = 0;
                    dr["DetJobCostTypeKey"] = 0;
                    dr["LogFC"] = DocComUtility.PT(DocOverallDisAmt * objDoc.DocSign, "C", "C");
                    dr["LogFD"] = DocComUtility.PT(DocOverallDisAmt * objDoc.DocSign, "C", "D");
                    dr["LogHC"] = DocComUtility.PT(DocCurrRate * DocOverallDisAmt * objDoc.DocSign, "C", "C");
                    dr["LogHD"] = DocComUtility.PT(DocCurrRate * DocOverallDisAmt * objDoc.DocSign, "C", "D");
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    dtPost.Rows.Add(dr);
                }
                #endregion

                #region Post Payment BK
                if (GFunc.IsNEZ(DocPaidAmtF) == false)
                {
                    if (GFunc.IsNEZ(DocPaidAccKey))
                        throw new TAException("Payment account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = 0;
                    dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                    dr["LogAccKey"] = DocPaidAccKey;
                    dr["LogTrans"] = PostType.BK;
                    dr["LogTransCode"] = PostTypeCode.BK;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = DocDeptKey;
                    dr["DocTranGrpKey"] = DocTranGrpKey;
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = GFunc.GetStringPropertyValue("DocPaidChqNum", objDoc);
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = 0M;
                    dr["DetItmDetSN"] = 0M;
                    dr["DetItmKey"] = 0;
                    dr["DetItmKeySelect"] = 0;
                    dr["DetItmDes"] = string.Empty;
                    dr["DetRef"] = GFunc.GetStringPropertyValue("DocPONum", objDoc);
                    dr["DetJobKey"] = 0;
                    dr["DetJobPhaseKey"] = 0;
                    dr["DetJobTaskKey"] = 0;
                    dr["DetJobCostTypeKey"] = 0;
                    dr["LogFC"] = DocComUtility.PT(DocPaidAmtF * objDoc.DocSign, "C", "C");
                    dr["LogFD"] = DocComUtility.PT(DocPaidAmtF * objDoc.DocSign, "C", "D");
                    dr["LogHC"] = DocComUtility.PT(DocPaidAmtF * objDoc.DocSign * DocCurrRate, "C", "C");
                    dr["LogHD"] = DocComUtility.PT(DocPaidAmtF * objDoc.DocSign * DocCurrRate, "C", "D");
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    dtPost.Rows.Add(dr);
                }
                #endregion

                #region Post Purchase

                dtItemsFilter = dtItems.AsEnumerable().Where(r => r.Field<int>("ItmType") <= 710 && r.Field<int>("LineType") == 1000);//"Assembly" Or "Charges" Or "Discount" Or "Non Stock" Or "Service" Or "Stock" Or "Finished GD" Or "Finished GDB" Or "StockB" And LineType=Detail Items                

                foreach (DataRow drv in dtItemsFilter)
                {
                    if (GFunc.IsNEZ(drv["ItmAmtH"]))
                        continue;

                    if (GFunc.IsNEZ(drv["ItmAccKey"]))
                        throw new TAException("Detail account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = drv["DocItmKey"];
                    dr["LogLineType"] = drv["LineType"];
                    dr["LogAccKey"] = drv["ItmAccKey"];
                    dr["LogTrans"] = PostType.ITM;
                    dr["LogTransCode"] = PostTypeCode.ITM;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = GFunc.NEInt(drv["ItmDeptKey"], 0);
                    dr["DocTranGrpKey"] = GFunc.NEInt(drv["ItmTranGrpKey"], 0);
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = string.Empty;
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = drv["ItmSN"]; ;
                    dr["DetItmDetSN"] = drv["ItmDetSN"];
                    dr["DetItmKey"] = GFunc.NEInt(drv["ItmKey"], 0);
                    dr["DetItmKeySelect"] = GFunc.NEInt(drv["ItmKeySelect"], 0);
                    dr["DetItmDes"] = drv["ItmDes"];
                    dr["DetRef"] = drv["APPOID"];
                    dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                    dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                    dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                    dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;

                    //Added by May on 20-Nov-2024.. because the discount will be deducted together with Item amount

                    if (objDoc.DocCodeKey==(int)GEnum.SystemCode.Purchase_Invoice && GFunc.NEInt(drv["ItmType"], 0) == (int)GEnum.ItemType.Discount 
                        && SysOptionUtility.LandedCostOption == 30 && dtItemsFilter.Count()>1) 
                        continue;
                    //mts 21-Aug-2018
                    //Modified by May on 20-Nov-2024 to deduct distributed discount amount
                    if (GFunc.NEDec(drv["DSQty"], 0) == 0 || GFunc.NEInt(drv["ItmType"], 0) == 710)//May modified on 24-Aug-2023 for discount Item to post as normal
                    {
                        if (SysOptionUtility.LandedCostOption == 30)//if option =Post with landed cost
                        {                           
                            dr["LogFC"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtF"], 0) + GFunc.NEDec(drv["ItmAddAmtF"], 0) - GFunc.NEDec(drv["ItmAddDisAmtF"], 0)) * objDoc.DocSign, "D", "C");
                            dr["LogFD"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtF"], 0) + GFunc.NEDec(drv["ItmAddAmtF"], 0) - GFunc.NEDec(drv["ItmAddDisAmtF"], 0)) * objDoc.DocSign, "D", "D");
                            dr["LogHC"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtH"], 0) + GFunc.NEDec(drv["ItmAddAmtH"], 0) - GFunc.NEDec(drv["ItmAddDisAmtH"], 0)) * objDoc.DocSign, "D", "C");
                            dr["LogHD"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtH"], 0) + GFunc.NEDec(drv["ItmAddAmtH"], 0) - GFunc.NEDec(drv["ItmAddDisAmtH"], 0)) * objDoc.DocSign, "D", "D");
                        }
                        else
                        {
                            dr["LogFC"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtF"], 0)) * objDoc.DocSign, "D", "C");
                            dr["LogFD"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtF"], 0)) * objDoc.DocSign, "D", "D");
                            dr["LogHC"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtH"], 0)) * objDoc.DocSign, "D", "C");
                            dr["LogHD"] = DocComUtility.PT((GFunc.NEDec(drv["ItmAmtH"], 0)) * objDoc.DocSign, "D", "D");
                        }
                    }
                    else
                    {
                        decimal amt = GFunc.RndC((GFunc.NEDec(drv["ItmQty"], 0) - GFunc.NEDec(drv["DSQty"], 0))
                            * GFunc.NEDec(drv["ItmPrice"], 0) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc), 2);
                        decimal amtF = GFunc.RndC((GFunc.NEDec(drv["ItmQty"], 0) - GFunc.NEDec(drv["DSQty"], 0))
                           * GFunc.NEDec(drv["ItmPrice"], 0), 2);
                        if (amt > 0)//mts 14-Oct-2018
                        {
                            if (SysOptionUtility.LandedCostOption == 30)//if option =Post with landed cost
                            {
                                dr["LogFC"] = DocComUtility.PT((amtF + GFunc.NEDec(drv["ItmAddAmtF"], 0) - GFunc.NEDec(drv["ItmAddDisAmtF"], 0)) * objDoc.DocSign, "D", "C");
                                dr["LogFD"] = DocComUtility.PT((amtF + GFunc.NEDec(drv["ItmAddAmtF"], 0) - GFunc.NEDec(drv["ItmAddDisAmtF"], 0)) * objDoc.DocSign, "D", "D");
                                dr["LogHC"] = DocComUtility.PT((amt + GFunc.NEDec(drv["ItmAddAmtH"], 0) - GFunc.NEDec(drv["ItmAddDisAmtH"], 0)) * objDoc.DocSign, "D", "C");
                                dr["LogHD"] = DocComUtility.PT((amt + GFunc.NEDec(drv["ItmAddAmtH"], 0) - GFunc.NEDec(drv["ItmAddDisAmtH"], 0)) * objDoc.DocSign, "D", "D");
                            }
                            else
                            {
                                dr["LogFC"] = DocComUtility.PT(amtF * objDoc.DocSign, "D", "C");
                                dr["LogFD"] = DocComUtility.PT(amtF * objDoc.DocSign, "D", "D");
                                dr["LogHC"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "C");
                                dr["LogHD"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "D");
                            }
                            dtPost.Rows.Add(dr);
                        }
                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = drv["DocItmKey"];
                        dr["LogLineType"] = drv["LineType"];

                        int acc = 0;
                        if (cn == null)
                        {
                            //if (SysOptionUtility.DatabaseBranchCode == "BHM")
                            //{
                            //    acc = SysOptionUtility.GetInt("DefaultDirectShipmentInventoryHolding");
                            //}
                            //else
                            {
                                acc = GFunc.NEInt(GFunc.ExecuteScalar("Select isnull(AccDSPHKey,0) from MST_Itm(nolock) where ItmKey=" + GFunc.NEStr(drv["ItmKey"], "0")), 0);
                                if (acc == 0)
                                    acc = SysOptionUtility.GetInt("DefaultAccDirectShipmentPurchase");
                            }
                        }
                        else
                        {
                            //if (SysOptionUtility.DatabaseBranchCode == "BHM")
                            //{
                            //    acc = SysOptionUtility.GetInt("DefaultDirectShipmentInventoryHolding", cn);
                            //}
                            //else
                            {
                                acc = GFunc.NEInt(GFunc.ExecuteScalar(cn, "Select isnull(AccDSPHKey,0) from MST_Itm(nolock) where ItmKey=" + GFunc.NEStr(drv["ItmKey"], "0")), 0);
                                if (acc == 0)
                                    acc = SysOptionUtility.GetInt("DefaultAccDirectShipmentPurchase", cn);
                            }
                        }

                        dr["LogAccKey"] = acc;
                        dr["LogTrans"] = PostType.ITM;
                        dr["LogTransCode"] = PostTypeCode.ITM;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = GFunc.NEInt(drv["ItmDeptKey"], 0);
                        dr["DocTranGrpKey"] = GFunc.NEInt(drv["ItmTranGrpKey"], 0);
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = DocCurrkey;
                        dr["DocCurrRate"] = DocCurrRate;
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = drv["ItmSN"]; ;
                        dr["DetItmDetSN"] = drv["ItmDetSN"];
                        dr["DetItmKey"] = GFunc.NEInt(drv["ItmKey"], 0);
                        dr["DetItmKeySelect"] = GFunc.NEInt(drv["ItmKeySelect"], 0);
                        dr["DetItmDes"] = drv["ItmDes"];
                        dr["DetRef"] = drv["APPOID"];
                        dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                        dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                        dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                        dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        amt = GFunc.RndC(GFunc.NEDec(drv["DSQty"], 0)
                            * GFunc.NEDec(drv["ItmPrice"], 0) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc), 2);
                        amtF = GFunc.RndC(GFunc.NEDec(drv["DSQty"], 0)
                            * GFunc.NEDec(drv["ItmPrice"], 0), 2);
                        if (SysOptionUtility.LandedCostOption == 30)//if option =Post with landed cost
                        {
                            dr["LogFC"] = DocComUtility.PT((amtF + GFunc.NEDec(drv["ItmAddAmtF"], 0) - GFunc.NEDec(drv["ItmAddDisAmtF"], 0)) * objDoc.DocSign, "D", "C");
                            dr["LogFD"] = DocComUtility.PT((amtF + GFunc.NEDec(drv["ItmAddAmtF"], 0) - GFunc.NEDec(drv["ItmAddDisAmtF"], 0)) * objDoc.DocSign, "D", "D");
                            dr["LogHC"] = DocComUtility.PT((amt + GFunc.NEDec(drv["ItmAddAmtH"], 0 ) - GFunc.NEDec(drv["ItmAddDisAmtH"], 0)) * objDoc.DocSign, "D", "C");
                            dr["LogHD"] = DocComUtility.PT((amt + GFunc.NEDec(drv["ItmAddAmtH"], 0 ) - GFunc.NEDec(drv["ItmAddDisAmtH"], 0)) * objDoc.DocSign, "D", "D");
                        }
                        else
                        {
                            dr["LogFC"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "C");
                            dr["LogFD"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "D");
                            dr["LogHC"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "C");
                            dr["LogHD"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "D");
                        }
                    }

                    dtPost.Rows.Add(dr);
                }
                #endregion

                #region Post Landed Cost

                if (SysOptionUtility.LandedCostOption == 30)//if option =Post with landed cost
                {
                    int[] batchItmTypes = new int[] { 110, 210, 310, 410 };//StockB,Finished GDB,Serial StockB,Serial Finished GDB

                    var getTotalAddCost = from row in dtItems.AsEnumerable()
                                          where (row.Field<int>("LineLinkKey") > 0 && batchItmTypes.Contains(row.Field<int>("ItmType")))
                                          || (row.Field<int>("LineLinkKey") == 0 && !batchItmTypes.Contains(row.Field<int>("ItmType")))
                                          group row by new
                                          {
                                              dKey = row.Field<int>("DocKey"),

                                          } into grp
                                          select new
                                          {
                                              DKey = grp.Key.dKey,
                                              ItmAddAmtF = grp.Sum(r => r.Field<decimal>("ItmAddAmtF")),
                                              ItmAddAmtH = grp.Sum(r => r.Field<decimal>("ItmAddAmtH"))
                                          };


                    foreach (var drv in getTotalAddCost)
                    {
                        if (GFunc.IsNEZ(drv.ItmAddAmtH))
                            continue;

                        if (GFunc.IsNEZ(DocAddCostAccKey))
                            throw new TAException("Landed cost account cannot be empty");

                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = 0;
                        dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                        dr["LogAccKey"] = GFunc.NEInt(DocAddCostAccKey, 0);
                        dr["LogTrans"] = PostType.LDC;
                        dr["LogTransCode"] = PostTypeCode.LDC;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = DocDeptKey;
                        dr["DocTranGrpKey"] = DocTranGrpKey;
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = DocCurrkey;
                        dr["DocCurrRate"] = DocCurrRate;
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = 0M;
                        dr["DetItmDetSN"] = 0M;
                        dr["DetItmKey"] = 0;
                        dr["DetItmKeySelect"] = 0;
                        dr["DetItmDes"] = "Landed Cost";
                        dr["DetRef"] = GFunc.GetStringPropertyValue("DocPONum", objDoc);
                        dr["DetJobKey"] = 0;
                        dr["DetJobPhaseKey"] = 0;
                        dr["DetJobTaskKey"] = 0;
                        dr["DetJobCostTypeKey"] = 0;
                        dr["LogFC"] = DocComUtility.PT(GFunc.NEDec(drv.ItmAddAmtF, 0) * objDoc.DocSign, "C", "C");
                        dr["LogFD"] = DocComUtility.PT(GFunc.NEDec(drv.ItmAddAmtF, 0) * objDoc.DocSign, "C", "D");
                        dr["LogHC"] = DocComUtility.PT(GFunc.NEDec(drv.ItmAddAmtH, 0) * objDoc.DocSign, "C", "C");
                        dr["LogHD"] = DocComUtility.PT(GFunc.NEDec(drv.ItmAddAmtH, 0) * objDoc.DocSign, "C", "D");
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        dtPost.Rows.Add(dr);
                    }
                }

                #endregion

                #region Post AP
                if (DocHome != 0)
                {
                    if (GFunc.IsNEZ(DocAccKey))
                        throw new TAException("AP account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = 0;
                    dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                    dr["LogAccKey"] = DocAccKey;
                    dr["LogTrans"] = PostType.AP;
                    dr["LogTransCode"] = PostTypeCode.AP;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = DocDeptKey;
                    dr["DocTranGrpKey"] = DocTranGrpKey;
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = string.Empty;
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = 0M;
                    dr["DetItmDetSN"] = 0M;
                    dr["DetItmKey"] = 0;
                    dr["DetItmKeySelect"] = 0;
                    dr["DetItmDes"] = string.Empty;
                    dr["DetRef"] = GFunc.GetStringPropertyValue("DocPONum", objDoc);
                    dr["DetJobKey"] = 0;
                    dr["DetJobPhaseKey"] = 0;
                    dr["DetJobTaskKey"] = 0;
                    dr["DetJobCostTypeKey"] = 0;
                    dr["LogFC"] = DocComUtility.PT(DocGrand * objDoc.DocSign, "C", "C");
                    dr["LogFD"] = DocComUtility.PT(DocGrand * objDoc.DocSign, "C", "D");
                    dr["LogHC"] = DocComUtility.PT(DocHome * objDoc.DocSign, "C", "C");
                    dr["LogHD"] = DocComUtility.PT(DocHome * objDoc.DocSign, "C", "D");
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    dtPost.Rows.Add(dr);
                }
                #endregion

                #region Post Gain AP
                if (DocApplyGainAmt != 0)
                {
                    if (GFunc.IsNEZ(DocAccKey))
                        throw new TAException("Gain account cannot be empty");

                    if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Purchase_Credit_Note)
                    {
                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = 0;
                        dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                        dr["LogAccKey"] = DocAccKey;
                        dr["LogTrans"] = PostType.GLB;
                        dr["LogTransCode"] = PostTypeCode.GLB;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = DocDeptKey;
                        dr["DocTranGrpKey"] = DocTranGrpKey;
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = DocCurrkey;
                        dr["DocCurrRate"] = DocCurrRate;
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = 0M;
                        dr["DetItmDetSN"] = 0M;
                        dr["DetItmKey"] = 0;
                        dr["DetItmKeySelect"] = 0;
                        dr["DetItmDes"] = string.Empty;
                        dr["DetRef"] = GFunc.GetStringPropertyValue("DocApplyIVID", objDoc);
                        dr["DetJobKey"] = 0;
                        dr["DetJobPhaseKey"] = 0;
                        dr["DetJobTaskKey"] = 0;
                        dr["DetJobCostTypeKey"] = 0;
                        dr["LogFC"] = 0;
                        dr["LogFD"] = 0;
                        dr["LogHC"] = DocComUtility.PT(DocApplyGainAmt, "D", "C");
                        dr["LogHD"] = DocComUtility.PT(DocApplyGainAmt, "D", "D");
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        dtPost.Rows.Add(dr);
                    }
                }
                #endregion

                #region Post Gain IC
                if (DocApplyGainAmt != 0)
                {
                    if (GFunc.IsNEZ(DocApplyGainAccKey))
                        throw new TAException("Gain account cannot be empty");

                    if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Purchase_Credit_Note)
                    {
                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = 0;
                        dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                        dr["LogAccKey"] = DocApplyGainAccKey;
                        dr["LogTrans"] = PostType.GLP;
                        dr["LogTransCode"] = PostTypeCode.GLP;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = DocDeptKey;
                        dr["DocTranGrpKey"] = DocTranGrpKey;
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = 1;
                        dr["DocCurrRate"] = 1;
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = 0M;
                        dr["DetItmDetSN"] = 0M;
                        dr["DetItmKey"] = 0;
                        dr["DetItmKeySelect"] = 0;
                        dr["DetItmDes"] = string.Empty;
                        dr["DetRef"] = GFunc.GetStringPropertyValue("DocApplyIVID", objDoc);
                        dr["DetJobKey"] = 0;
                        dr["DetJobPhaseKey"] = 0;
                        dr["DetJobTaskKey"] = 0;
                        dr["DetJobCostTypeKey"] = 0;
                        dr["LogFC"] = 0;
                        dr["LogFD"] = 0;
                        dr["LogHC"] = DocComUtility.PT(DocApplyGainAmt, "C", "C");
                        dr["LogHD"] = DocComUtility.PT(DocApplyGainAmt, "C", "D");
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        dtPost.Rows.Add(dr);
                    }
                }
                #endregion

                #region Post Purchase APPD Reverse
                if (objDoc.DocCodeKey == (int)GEnum.SystemCode.Purchase_Invoice)
                {
                    //Call SP (Doc_PrepareAPPDReversePost) here to retrive 2 dt
                    List<SqlParameter> pdParmList = new List<SqlParameter>();
                    pdParmList.Add(new SqlParameter("@xmlDocDetail", GFunc.ConvertDataTableToXML(dtItems)));


                    DataSet dsPD = GFunc.ExecuteProcDataSet("Doc_PrepareAPPDReversePost", pdParmList);//Tables[0]=APPDDetItm, Table[1]=APPD

                    foreach (DataRow drv in dsPD.Tables[0].Rows)
                    {
                        if (GFunc.IsNEZ(drv["PDItmAmtH"]))
                            continue;

                        if (GFunc.IsNEZ(drv["PDItmAccKey"]))
                            throw new TAException("Detail account cannot be empty");

                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = drv["DocItmKey"];
                        dr["LogLineType"] = drv["LineType"];
                        dr["LogAccKey"] = drv["PDItmAccKey"];
                        dr["LogTrans"] = PostType.ITMREV;
                        dr["LogTransCode"] = PostTypeCode.ITMREV;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = GFunc.NEInt(drv["ItmDeptKey"], 0);
                        dr["DocTranGrpKey"] = GFunc.NEInt(drv["ItmTranGrpKey"], 0);
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = drv["PDDocCurrKey"];
                        dr["DocCurrRate"] = drv["PDDocCurrRate"];
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = drv["ItmSN"];
                        dr["DetItmDetSN"] = drv["ItmDetSN"];
                        dr["DetItmKey"] = GFunc.NEInt(drv["ItmKey"], 0);
                        dr["DetItmKeySelect"] = GFunc.NEInt(drv["ItmKeySelect"], 0);
                        dr["DetItmDes"] = drv["ItmDes"];
                        dr["DetRef"] = drv["APPDID"];
                        dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                        dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                        dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                        dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                        dr["LogFC"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtF"], 0) * objDoc.DocSign, "C", "C");//C, PDItmAmtF
                        dr["LogFD"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtF"], 0) * objDoc.DocSign, "C", "D");//C, PDItmAmtF
                        dr["LogHC"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtH"], 0) * objDoc.DocSign, "C", "C");//C, PDItmAmtH
                        dr["LogHD"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtH"], 0) * objDoc.DocSign, "C", "D");//C, PDItmAmtH
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        dtPost.Rows.Add(dr);
                    }

                    int Num = 0;
                    if (dtPost != null)
                    {
                        if (dtPost.Rows.Count > 0)
                            Num = GFunc.NEInt(dtPost.AsEnumerable().Max(k => k.Field<int>("LogDItm")), 0);
                    }

                    if (DocHome != 0)
                    {
                        if (GFunc.IsNEZ(DocAccKey))
                            throw new TAException("AP account cannot be empty");

                        foreach (DataRow drv in dsPD.Tables[1].Rows)//Tables[1] LinkAPPD,HDR
                        {
                            Num = Num + 1;
                            dr = dtPost.NewRow();
                            dr["LogDC"] = objDoc.DocCodeKey;
                            dr["LogDK"] = objDoc.DocKey;
                            dr["LogDItm"] = Num;
                            dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                            dr["LogAccKey"] = drv["PDDocAccKey"];
                            dr["LogTrans"] = PostType.ITMREV;
                            dr["LogTransCode"] = PostTypeCode.ITMREV;
                            dr["LogTaxKey"] = 0;
                            dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                            dr["DocID"] = docID;
                            dr["DocDate"] = objDoc.DocDate;
                            dr["DocPeriod"] = DocPeriod;
                            dr["DocBranchKey"] = DocBranchKey;
                            dr["DocDeptKey"] = DocDeptKey;
                            dr["DocTranGrpKey"] = DocTranGrpKey;
                            dr["DocGrpKey"] = DocGrpKey;
                            dr["DocType"] = objDoc.DocType;
                            dr["DocTypeNm"] = objDoc.DocTypeNm;
                            dr["DocCurrkey"] = drv["PDDocCurrKey"];//Get APPD DocCurrKey;
                            dr["DocCurrRate"] = drv["PDDocCurrRate"];//Get APPD DocCurrRate;
                            dr["DocCVKey"] = DocCVKey;
                            dr["DocCVNmDoc"] = DocCVNmDoc;
                            dr["DocChqNum"] = string.Empty;
                            dr["DocRef"] = DocRef;
                            dr["DocDes"] = DocDes;
                            dr["DetItmSN"] = 0M;
                            dr["DetItmDetSN"] = 0M;
                            dr["DetItmKey"] = 0;
                            dr["DetItmKeySelect"] = 0;
                            dr["DetItmDes"] = string.Empty;
                            dr["DetRef"] = drv["APPDID"];
                            dr["DetJobKey"] = 0;
                            dr["DetJobPhaseKey"] = 0;
                            dr["DetJobTaskKey"] = 0;
                            dr["DetJobCostTypeKey"] = 0;
                            dr["LogFC"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtF"], 0M), "D", "C");//D, Sum of ItmAmtF Groupby PD DocKey
                            dr["LogFD"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtF"], 0M), "D", "D");//D, Sum of ItmAmtF Groupby PD DocKey
                            dr["LogHC"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtH"], 0M), "D", "C");//D, Sum of ItmAmtH Groupby PD DocKey
                            dr["LogHD"] = DocComUtility.PT(GFunc.NEDec(drv["PDItmAmtH"], 0M), "D", "D");//D, Sum of ItmAmtH Groupby PD DocKey
                            dr["LogRecon"] = false;
                            dr["LogReconPeriod"] = 0;
                            dtPost.Rows.Add(dr);
                        }
                    }
                }
                #endregion

                DTPostRnd(cn, objDoc, dtPost);
                return dtPost;
            }
            catch (TAException taex)
            {
                throw Error(taex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
            finally
            {
                dr = null;
                dtIsCustomGST = null;
                dtItems = null;
            }

        }
        private static DataTable DTPostAPPD(SqlConnection cn, Document objDoc, DataTable dtItems)
        {
            #region Declaration
            IEnumerable<DataRow> dtItemsFilter = null;
            DataRow dr = null;
            DataTable dtPost = new DataTable();
            #region dtPost field list
            dtPost.Columns.Add("LogKey", typeof(int));
            dtPost.Columns.Add("LogDC", typeof(int));
            dtPost.Columns.Add("LogDK", typeof(int));
            dtPost.Columns.Add("LogDItm", typeof(int));
            dtPost.Columns.Add("LogLineType", typeof(int));
            dtPost.Columns.Add("LogAccKey", typeof(int));
            dtPost.Columns.Add("LogTrans", typeof(string));
            dtPost.Columns.Add("LogTaxKey", typeof(int));
            dtPost.Columns.Add("LogTransCode", typeof(string));
            dtPost.Columns.Add("LogSeq", typeof(decimal));
            dtPost.Columns.Add("DocID", typeof(string));
            dtPost.Columns.Add("DocDate", typeof(DateTime));
            dtPost.Columns.Add("DocPeriod", typeof(decimal));
            dtPost.Columns.Add("DocBranchKey", typeof(int));
            dtPost.Columns.Add("DocDeptKey", typeof(int));
            dtPost.Columns.Add("DocTranGrpKey", typeof(int));
            dtPost.Columns.Add("DocGrpKey", typeof(int));
            dtPost.Columns.Add("DocType", typeof(int));
            dtPost.Columns.Add("DocTypeNm", typeof(string));
            dtPost.Columns.Add("DocCurrkey", typeof(int));
            dtPost.Columns.Add("DocCurrRate", typeof(decimal));
            dtPost.Columns.Add("DocCVKey", typeof(int));
            dtPost.Columns.Add("DocCVNmDoc", typeof(string));
            dtPost.Columns.Add("DocChqNum", typeof(string));
            dtPost.Columns.Add("DocRef", typeof(string));
            dtPost.Columns.Add("DocDes", typeof(string));
            dtPost.Columns.Add("DetItmSN", typeof(decimal));
            dtPost.Columns.Add("DetItmDetSN", typeof(decimal));
            dtPost.Columns.Add("DetItmKey", typeof(int));
            dtPost.Columns.Add("DetItmKeySelect", typeof(int));
            dtPost.Columns.Add("DetItmDes", typeof(string));
            dtPost.Columns.Add("DetRef", typeof(string));
            dtPost.Columns.Add("DetJobKey", typeof(int));
            dtPost.Columns.Add("DetJobPhaseKey", typeof(int));
            dtPost.Columns.Add("DetJobTaskKey", typeof(int));
            dtPost.Columns.Add("DetJobCostTypeKey", typeof(int));
            dtPost.Columns.Add("LogFC", typeof(decimal));
            dtPost.Columns.Add("LogFD", typeof(decimal));
            dtPost.Columns.Add("LogHC", typeof(decimal));
            dtPost.Columns.Add("LogHD", typeof(decimal));
            dtPost.Columns.Add("LogRecon", typeof(bool));
            dtPost.Columns.Add("LogReconPeriod", typeof(int));
            #endregion

            decimal? DocPeriod = Convert.ToInt32(GFunc.NEDateTime(objDoc.DocDate, DateTime.Today).ToString("yyyyMM"));
            int? DocBranchKey = GFunc.GetIntPropertyValue("BranchKey", objDoc);
            int? DocDeptKey = GFunc.GetIntPropertyValue("DocDeptKey", objDoc);
            int? DocTranGrpKey = GFunc.GetIntPropertyValue("DocTranGrpKey", objDoc);
            int? DocGrpKey = GFunc.GetIntPropertyValue("DocGrpKey", objDoc);
            int? DocCurrkey = GFunc.GetIntPropertyValue("DocCurrKey", objDoc);
            decimal? DocCurrRate = GFunc.GetDecimalPropertyValue("DocCurrRate", objDoc);
            int? DocCVKey = GFunc.GetIntPropertyValue("DocConKey", objDoc);
            string DocCVNmDoc = GFunc.GetStringPropertyValue("DocConNm", objDoc);
            string DocRef = GFunc.GetStringPropertyValue("DocRef", objDoc);
            string DocDes = GFunc.GetStringPropertyValue("DocDes", objDoc);
            int? DocOverallDisAcc = GFunc.GetIntPropertyValue("DocOverallDisAcc", objDoc);
            decimal? DocOverallDisAmt = GFunc.GetDecimalPropertyValue("DocOverallDisAmt", objDoc);
            decimal? DocGrand = GFunc.GetDecimalPropertyValue("DocGrand", objDoc);
            decimal? DocHome = GFunc.GetDecimalPropertyValue("DocHome", objDoc);
            int? DocAccKey = GFunc.GetIntPropertyValue("DocAccKey", objDoc);

            #endregion

            try
            {
                string docID = objDoc.DocID;

                #region Post Overall Discount
                if (GFunc.IsNEZ(DocOverallDisAmt) == false)
                {
                    if (GFunc.IsNEZ(DocOverallDisAcc))
                        throw new TAException("Overall discount account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = 0;
                    dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                    dr["LogAccKey"] = DocOverallDisAcc;
                    dr["LogTrans"] = PostType.DIS;
                    dr["LogTransCode"] = PostTypeCode.DIS;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = DocDeptKey;
                    dr["DocTranGrpKey"] = DocTranGrpKey;
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = string.Empty;
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = 0M;
                    dr["DetItmDetSN"] = 0M;
                    dr["DetItmKey"] = 0;
                    dr["DetItmKeySelect"] = 0;
                    dr["DetItmDes"] = string.Empty;
                    dr["DetRef"] = GFunc.GetStringPropertyValue("DocPONum", objDoc);
                    dr["DetJobKey"] = 0;
                    dr["DetJobPhaseKey"] = 0;
                    dr["DetJobTaskKey"] = 0;
                    dr["DetJobCostTypeKey"] = 0;
                    dr["LogFC"] = DocComUtility.PT(DocOverallDisAmt * objDoc.DocSign, "C", "C");
                    dr["LogFD"] = DocComUtility.PT(DocOverallDisAmt * objDoc.DocSign, "C", "D");
                    dr["LogHC"] = DocComUtility.PT(DocCurrRate * DocOverallDisAmt * objDoc.DocSign, "C", "C");
                    dr["LogHD"] = DocComUtility.PT(DocCurrRate * DocOverallDisAmt * objDoc.DocSign, "C", "D");
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    dtPost.Rows.Add(dr);
                }
                #endregion

                #region Post Itm Purchase

                dtItemsFilter = dtItems.AsEnumerable().Where(r => r.Field<int>("ItmType") <= 710 && r.Field<int>("LineType") == 1000);

                foreach (DataRow drv in dtItemsFilter)
                {
                    if (GFunc.IsNEZ(drv["ItmAmtH"]))
                        continue;

                    if (GFunc.IsNEZ(drv["ItmAccKey"]))
                        throw new TAException("Detail account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = drv["DocItmKey"];
                    dr["LogLineType"] = drv["LineType"];
                    dr["LogAccKey"] = drv["ItmAccKey"];
                    dr["LogTrans"] = PostType.ITM;
                    dr["LogTransCode"] = PostTypeCode.ITM;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = GFunc.NEInt(drv["ItmDeptKey"], 0);
                    dr["DocTranGrpKey"] = GFunc.NEInt(drv["ItmTranGrpKey"], 0);
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = string.Empty;
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = drv["ItmSN"];
                    dr["DetItmDetSN"] = drv["ItmDetSN"];
                    dr["DetItmKey"] = drv["ItmKey"];
                    dr["DetItmKeySelect"] = drv["ItmKeySelect"];
                    dr["DetItmDes"] = drv["ItmDes"];
                    dr["DetRef"] = drv["APPOID"];
                    dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                    dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                    dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                    dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    //mts 21-Aug-2018
                    if (GFunc.NEDec(drv["DSQty"], 0) == 0 || GFunc.NEInt(drv["ItmType"],0)==710)//May modified on 24-Aug-2023 for discount Item to post as normal
                    {
                        dr["LogFC"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtF"], 0) * objDoc.DocSign, "D", "C");
                        dr["LogFD"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtF"], 0) * objDoc.DocSign, "D", "D");
                        dr["LogHC"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtH"], 0) * objDoc.DocSign, "D", "C");
                        dr["LogHD"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtH"], 0) * objDoc.DocSign, "D", "D");
                    }
                    else
                    {
                        decimal amt = GFunc.RndC((GFunc.NEDec(drv["ItmQty"], 0) - GFunc.NEDec(drv["DSQty"], 0))
                            * GFunc.NEDec(drv["ItmPrice"], 0) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc), 2);
                        decimal amtF = GFunc.RndC((GFunc.NEDec(drv["ItmQty"], 0) - GFunc.NEDec(drv["DSQty"], 0))
                           * GFunc.NEDec(drv["ItmPrice"], 0), 2);
                        if (amt > 0)
                        {
                            dr["LogFC"] = DocComUtility.PT(amtF * objDoc.DocSign, "D", "C");
                            dr["LogFD"] = DocComUtility.PT(amtF * objDoc.DocSign, "D", "D");
                            dr["LogHC"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "C");
                            dr["LogHD"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "D");
                            dtPost.Rows.Add(dr);
                        }

                        //Posting for direct shipment
                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = drv["DocItmKey"];
                        dr["LogLineType"] = drv["LineType"];
                        //   dr["LogAccKey"] = drv["ItmAccKey"];
                        int acc = 0;
                        if (cn == null)
                        {
                            acc = GFunc.NEInt(GFunc.ExecuteScalar("Select isnull(AccDSPHKey,0) from MST_Itm(nolock) where ItmKey=" + GFunc.NEStr(drv["ItmKey"], "0")), 0);
                            if (acc == 0)
                                acc = SysOptionUtility.GetInt("DefaultAccDirectShipmentPurchase");
                        }
                        else
                        {
                            acc = GFunc.NEInt(GFunc.ExecuteScalar(cn, "Select isnull(AccDSPHKey,0) from MST_Itm(nolock) where ItmKey=" + GFunc.NEStr(drv["ItmKey"], "0")), 0);
                            acc = SysOptionUtility.GetInt("DefaultAccDirectShipmentPurchase", cn);
                        }

                        dr["LogAccKey"] = acc;
                        dr["LogTrans"] = PostType.ITM;
                        dr["LogTransCode"] = PostTypeCode.ITM;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = GFunc.NEInt(drv["ItmDeptKey"], 0);
                        dr["DocTranGrpKey"] = GFunc.NEInt(drv["ItmTranGrpKey"], 0);
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = DocCurrkey;
                        dr["DocCurrRate"] = DocCurrRate;
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = drv["ItmSN"];
                        dr["DetItmDetSN"] = drv["ItmDetSN"];
                        dr["DetItmKey"] = drv["ItmKey"];
                        dr["DetItmKeySelect"] = drv["ItmKeySelect"];
                        dr["DetItmDes"] = drv["ItmDes"];
                        dr["DetRef"] = drv["APPOID"];
                        dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                        dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                        dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                        dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        amt = GFunc.RndC(GFunc.NEDec(drv["DSQty"], 0)
                            * GFunc.NEDec(drv["ItmPrice"], 0) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc), 2);
                        amtF = GFunc.RndC(GFunc.NEDec(drv["DSQty"], 0)
                           * GFunc.NEDec(drv["ItmPrice"], 0), 2);
                        dr["LogFC"] = DocComUtility.PT(amtF * objDoc.DocSign, "D", "C");
                        dr["LogFD"] = DocComUtility.PT(amtF * objDoc.DocSign, "D", "D");
                        dr["LogHC"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "C");
                        dr["LogHD"] = DocComUtility.PT(amt * objDoc.DocSign, "D", "D");
                    }
                    dtPost.Rows.Add(dr);
                }
                #endregion

                #region Post AP Accrual
                if (DocHome != 0)
                {
                    if (GFunc.IsNEZ(DocAccKey))
                        throw new TAException("GL account cannot be empty");

                    dr = dtPost.NewRow();
                    dr["LogDC"] = objDoc.DocCodeKey;
                    dr["LogDK"] = objDoc.DocKey;
                    dr["LogDItm"] = 0;
                    dr["LogLineType"] = (int)GEnum.RecDetailType.NoDetail;
                    dr["LogAccKey"] = DocAccKey;
                    dr["LogTrans"] = PostType.AP;
                    dr["LogTransCode"] = PostTypeCode.AP;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocHeader;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
                    dr["DocPeriod"] = DocPeriod;
                    dr["DocBranchKey"] = DocBranchKey;
                    dr["DocDeptKey"] = DocDeptKey;
                    dr["DocTranGrpKey"] = DocTranGrpKey;
                    dr["DocGrpKey"] = DocGrpKey;
                    dr["DocType"] = objDoc.DocType;
                    dr["DocTypeNm"] = objDoc.DocTypeNm;
                    dr["DocCurrkey"] = DocCurrkey;
                    dr["DocCurrRate"] = DocCurrRate;
                    dr["DocCVKey"] = DocCVKey;
                    dr["DocCVNmDoc"] = DocCVNmDoc;
                    dr["DocChqNum"] = string.Empty;
                    dr["DocRef"] = DocRef;
                    dr["DocDes"] = DocDes;
                    dr["DetItmSN"] = 0M;
                    dr["DetItmDetSN"] = 0M;
                    dr["DetItmKey"] = 0;
                    dr["DetItmKeySelect"] = 0;
                    dr["DetItmDes"] = string.Empty;
                    dr["DetRef"] = GFunc.GetStringPropertyValue("DocPONum", objDoc);
                    dr["DetJobKey"] = 0;
                    dr["DetJobPhaseKey"] = 0;
                    dr["DetJobTaskKey"] = 0;
                    dr["DetJobCostTypeKey"] = 0;
                    dr["LogFC"] = DocComUtility.PT(DocGrand * objDoc.DocSign, "C", "C");
                    dr["LogFD"] = DocComUtility.PT(DocGrand * objDoc.DocSign, "C", "D");
                    dr["LogHC"] = DocComUtility.PT(DocHome * objDoc.DocSign, "C", "C");
                    dr["LogHD"] = DocComUtility.PT(DocHome * objDoc.DocSign, "C", "D");
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    dtPost.Rows.Add(dr);
                }
                #endregion

                DTPostRnd(cn, objDoc, dtPost);

                return dtPost;
            }
            catch (TAException taex)
            {
                throw Error(taex);
            }
            catch (Exception ex)
            {
                throw Error(ex);
            }
            finally
            {
                dr = null;
            }
        }//Completed
        private static DataTable DTPostAPPY(SqlConnection cn, Document objDoc, DataTable dtItems, DataTable dtExp)
        {
            #region Declaration
            IEnumerable<DataRow> dtItemFilter = null;
            DataTable dtTaxGrpList = new DataTable();
