                    dr["LogTrans"] = PostType.ItmDisP;
                    dr["LogTransCode"] = PostTypeCode.ItmDisP;
                    dr["LogTaxKey"] = 0;
                    dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                    dr["DocID"] = docID;
                    dr["DocDate"] = objDoc.DocDate;
