                    dr["DetItmKeySelect"] = drv["ItmKeySelect"];
                    dr["DetItmDes"] = drv["ItmDes"];
                    dr["DetRef"] = drv["ARDOID"];
                    dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                    dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                    dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                    dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                    dr["LogRecon"] = false;
                    dr["LogReconPeriod"] = 0;
                    //mts 21-Aug-2018
                    if (GFunc.NEDec(drv["DSQty"], 0) == 0 || GFunc.NEInt(drv["ItmType"], 0) == 710)//May modified on 24-Aug-2023 for discount Item to post as normal
                    {
                        dr["LogFC"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtF"], 0) * objDoc.DocSign, "C", "C");
                        dr["LogFD"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtF"], 0) * objDoc.DocSign, "C", "D");
                        dr["LogHC"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtH"], 0) * objDoc.DocSign, "C", "C");
                        dr["LogHD"] = DocComUtility.PT(GFunc.NEDec(drv["ItmAmtH"], 0) * objDoc.DocSign, "C", "D");
                    }
                    else
                    {
                        decimal amt = GFunc.RndC((GFunc.NEDec(drv["ItmQty"], 0) - GFunc.NEDec(drv["DSQty"], 0))
                            * GFunc.NEDec(drv["ItmPrice"], 0) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc), 2);

                        if (amt > 0)
                        {
                            dr["LogFC"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "C");
                            dr["LogFD"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "D");
                            dr["LogHC"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "C");
                            dr["LogHD"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "D");
                            dtPost.Rows.Add(dr);
                        }
                        //Posting for direct shipment
                        dr = dtPost.NewRow();
                        dr["LogDC"] = objDoc.DocCodeKey;
                        dr["LogDK"] = objDoc.DocKey;
                        dr["LogDItm"] = drv["DocItmKey"];
                        dr["LogLineType"] = drv["LineType"];

                        int acc = 0;
                        if (cn == null)
                        {
                            acc = GFunc.NEInt(GFunc.ExecuteScalar("Select isnull(AccDSICKey,0) from MST_Itm(nolock) where ItmKey=" + GFunc.NEStr(drv["ItmKey"], "0")), 0);
                            if (acc == 0)
                                acc = SysOptionUtility.GetInt("DefaultAccDirectShipmentSales");
                        }
                        else
                        {
                            acc = GFunc.NEInt(GFunc.ExecuteScalar(cn, "Select isnull(AccDSICKey,0) from MST_Itm(nolock) where ItmKey=" + GFunc.NEStr(drv["ItmKey"], "0")), 0);
                            if (acc == 0)  //added on 21-Oct-2022
                                acc = SysOptionUtility.GetInt("DefaultAccDirectShipmentSales", cn);
                        }

                        dr["LogAccKey"] = acc;
                        dr["LogTrans"] = PostType.ITM;
                        dr["LogTransCode"] = PostTypeCode.ITM;
                        dr["LogTaxKey"] = 0;
                        dr["LogSeq"] = (int)GEnum.GLLogSeq.DocDetItm;
                        dr["DocID"] = docID;
                        dr["DocDate"] = objDoc.DocDate;
                        dr["DocPeriod"] = DocPeriod;
                        dr["DocBranchKey"] = DocBranchKey;
                        dr["DocDeptKey"] = GFunc.NEInt(drv["ItmDeptKey"], 0);
                        dr["DocTranGrpKey"] = GFunc.NEInt(drv["ItmTranGrpKey"], 0);
                        dr["DocGrpKey"] = DocGrpKey;
                        dr["DocType"] = objDoc.DocType;
                        dr["DocTypeNm"] = objDoc.DocTypeNm;
                        dr["DocCurrkey"] = DocCurrkey;
                        dr["DocCurrRate"] = DocCurrRate;
                        dr["DocCVKey"] = DocCVKey;
                        dr["DocCVNmDoc"] = DocCVNmDoc;
                        dr["DocChqNum"] = string.Empty;
                        dr["DocRef"] = DocRef;
                        dr["DocDes"] = DocDes;
                        dr["DetItmSN"] = drv["ItmSN"];
                        dr["DetItmDetSN"] = drv["ItmDetSN"];
                        dr["DetItmKey"] = drv["ItmKey"];
                        dr["DetItmKeySelect"] = drv["ItmKeySelect"];
                        dr["DetItmDes"] = drv["ItmDes"];
                        dr["DetRef"] = drv["ARDOID"];
                        dr["DetJobKey"] = GFunc.NEInt(drv["ItmJobKey"], 0);
                        dr["DetJobPhaseKey"] = GFunc.NEInt(drv["ItmJobPhaseKey"], 0);
                        dr["DetJobTaskKey"] = GFunc.NEInt(drv["ItmJobTaskKey"], 0);
                        dr["DetJobCostTypeKey"] = GFunc.NEInt(drv["ItmJobCostTypeKey"], 0);
                        dr["LogRecon"] = false;
                        dr["LogReconPeriod"] = 0;
                        amt = GFunc.RndC(GFunc.NEDec(drv["DSQty"], 0)
                            * GFunc.NEDec(drv["ItmPrice"], 0) * (decimal)GFunc.GetPropertyValue("DocCurrRate", objDoc), 2);
                        dr["LogFC"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "C");
                        dr["LogFD"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "D");
                        dr["LogHC"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "C");
                        dr["LogHD"] = DocComUtility.PT(amt * objDoc.DocSign, "C", "D");
                    }

                    dtPost.Rows.Add(dr);
