                    if ((int)drv["ItmType"] == (int)GEnum.ItemType.StockB || (int)drv["ItmType"] == (int)GEnum.ItemType.Finished_GDB)
                    {
                        dr["LogFC"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmBatchQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "C");
                        dr["LogFD"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmBatchQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "D");
                        dr["LogHC"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmBatchQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "C");
                        dr["LogHD"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmBatchQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "D");
                    }
                    else
                    {
                        dr["LogFC"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "C");
                        dr["LogFD"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "D");
                        dr["LogHC"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "C");
                        dr["LogHD"] = DocComUtility.PT(GFunc.RndC(GFunc.NEDec(drv["ItmQty"], 0) * GFunc.NEDec(drv["ItmCost"], 0), GVar.RndDecs.Amtpt), "D", "D");
                    }
                    dtPost.Rows.Add(dr);
                }
                #endregion

                DTPostRnd(cn, objDoc, dtPost);
                return dtPost;
            }
            catch (TAException taex)
